/* Déclic — Notions fondamentales : analyse (1) : les réels, bornes, intervalles, suites */
(()=>{
/* ---------- helpers locaux ---------- */
const VF=b=>`<b style="color:${b?'var(--ok)':'var(--bad)'}">${b?'V':'F'}</b>`;
const tab=(head,rows,hl=-1)=>`<table style="border-collapse:collapse;margin:6px auto"><tr>${head.map(h=>`<th style="border-bottom:2px solid var(--line);padding:4px 9px">${h}</th>`).join('')}</tr>${rows.map((r,i)=>`<tr${i===hl?' style="background:color-mix(in srgb,var(--accent) 25%,transparent)"':''}>${r.map(c=>`<td style="padding:4px 9px;text-align:center;border-bottom:1px solid var(--line)">${typeof c==='boolean'?VF(c):c}</td>`).join('')}</tr>`).join('')}</table>`;
// Axe réel horizontal : axe([xmin,xmax],{h,step,lab}) → objet plane enrichi de xr
function axe(xr,o={}){ const P=plane({x:xr,y:[-1,1.2],h:o.h||96,grid:false,axes:false,w:320}); P.xr=xr;
  P.arrow(xr[0],0,xr[1],0,{c:'var(--muted)',w:1.5,hs:8});
  const st=o.step||1; for(let k=Math.ceil(xr[0]/st)*st;k<xr[1]-0.25;k+=st){ P.seg(k,-0.1,k,0.1,{c:'var(--muted)',w:1.5}); if(o.lab!==false) P.text(k,-0.1,fmt(k),{a:'middle',dy:16,c:'var(--muted)',s:11}); }
  return P; }
// Intervalle dessiné sur l’axe P : bornes a, b (null = infini), ca/cb = borne fermée ?
function inter(P,a,b,ca,cb,o={}){ const c=o.c||'var(--accent)', y=o.y??0, lo=a===null?P.xr[0]:a, hi=b===null?P.xr[1]:b;
  P.seg(lo,y,hi,y,{c,w:o.w||7,op:.85});
  if(a!==null) P.circ(a,y,0.13,{c,w:2.5,fill:ca?c:'var(--surface)',fo:1});
  if(b!==null) P.circ(b,y,0.13,{c,w:2.5,fill:cb?c:'var(--surface)',fo:1});
  return P; }
// Les neuf types d’intervalles, avec a = 1 et b = 4 pour les figures
const TYPES=[
 {n:'[<i>a</i> ; <i>b</i>]',d:'<i>a</i> ≤ <i>x</i> ≤ <i>b</i>',a:1,b:4,ca:true,cb:true,t:(x,a,b)=>x>=a&&x<=b},
 {n:'[<i>a</i> ; <i>b</i>[',d:'<i>a</i> ≤ <i>x</i> &lt; <i>b</i>',a:1,b:4,ca:true,cb:false,t:(x,a,b)=>x>=a&&x<b},
 {n:']<i>a</i> ; <i>b</i>]',d:'<i>a</i> &lt; <i>x</i> ≤ <i>b</i>',a:1,b:4,ca:false,cb:true,t:(x,a,b)=>x>a&&x<=b},
 {n:']<i>a</i> ; <i>b</i>[',d:'<i>a</i> &lt; <i>x</i> &lt; <i>b</i>',a:1,b:4,ca:false,cb:false,t:(x,a,b)=>x>a&&x<b},
 {n:'[<i>a</i> ; +∞[',d:'<i>x</i> ≥ <i>a</i>',a:1,b:null,ca:true,cb:false,t:(x,a,b)=>x>=a},
 {n:']<i>a</i> ; +∞[',d:'<i>x</i> &gt; <i>a</i>',a:1,b:null,ca:false,cb:false,t:(x,a,b)=>x>a},
 {n:']−∞ ; <i>b</i>]',d:'<i>x</i> ≤ <i>b</i>',a:null,b:4,ca:false,cb:true,t:(x,a,b)=>x<=b},
 {n:']−∞ ; <i>b</i>[',d:'<i>x</i> &lt; <i>b</i>',a:null,b:4,ca:false,cb:false,t:(x,a,b)=>x<b},
 {n:']−∞ ; +∞[ = ℝ',d:'tout réel <i>x</i>',a:null,b:null,ca:false,cb:false,t:()=>true},
];
// Suite dessinée : points (n, u(n)) pour n de n0 à N, avec options de bande autour de L
function suite(u,o={}){ const n0=o.n0??1, N=o.N||20, ys=[]; for(let n=n0;n<=N;n++) ys.push(u(n));
  const ymin=o.y?o.y[0]:Math.min(...ys)-0.5, ymax=o.y?o.y[1]:Math.max(...ys)+0.5;
  const P=plane({x:[-0.8,N+1],y:[ymin,ymax],h:o.h||210,grid:false,lx:o.lx||5,ly:o.ly||1});
  if(o.L!==undefined){ if(o.e) P.rect(-0.8,o.L-o.e,N+1.8,2*o.e,{fill:'var(--ok)',fo:.15,c:null}); P.seg(-0.8,o.L,N+1,o.L,{c:'var(--ok)',w:1.5,dash:true}); }
  if(o.N0!==undefined){ P.seg(o.N0,ymin,o.N0,ymax,{c:'var(--muted)',w:1.5}); P.text(o.N0,ymax,'N',{dx:4,dy:14}); }
  for(let n=n0;n<=N;n++){ const y=u(n); let c='var(--accent)'; if(o.N0!==undefined&&n<o.N0) c='var(--muted)'; else if(o.e!==undefined&&Math.abs(y-o.L)>=o.e-1e-12) c='var(--bad)'; P.dot(n,y,{r:3.5,c}); }
  return P; }
const sq2=Math.SQRT2;

COURS.push(
/* ===================== 1. ℝ, UN CORPS COMMUTATIF ORDONNÉ ===================== */
{subj:'gred',sem:'ana',id:'gred-reels',h:'ℝ, un corps commutatif ordonné',p:'Pourquoi les fractions ne suffisent pas, et quelles règles exactes gouvernent le calcul sur les réels : les axiomes de corps, les axiomes d’ordre, les inégalités et la valeur absolue.',steps:[
  {kind:'Théorie',h:'Pourquoi les fractions ne suffisent pas',
   p:`<p>Dans la partie précédente, ℚ a été construit comme corps des fractions de ℤ. On y additionne, multiplie, divise sans sortir de ℚ. Pourtant, dès la géométrie la plus simple, ℚ a un trou.</p>
<div class="blk" data-t="Rappel"><p>Un <b>rationnel</b> est un quotient <i>p</i>/<i>q</i> d’entiers, avec <i>q</i> ≠ 0. Toute fraction a une écriture <b>irréductible</b> : on peut choisir <i>p</i> et <i>q</i> sans diviseur commun autre que 1.</p></div>
<div class="idea"><p>Prends un carré de côté 1. Par le théorème de Pythagore, sa diagonale <i>d</i> vérifie <i>d</i>² = 1² + 1² = 2. Cette diagonale existe : on la trace à la règle. Si l’on veut qu’à chaque longueur corresponde un nombre, il faut un nombre dont le carré vaut 2. On le note √2.</p></div>
<div class="ex"><p>Essayons avec des fractions : (7/5)² = 49/25 = 1,96 et (17/12)² = 289/144 ≈ 2,0069. On s’approche de 2 par en dessous et par en dessus, mais on ne tombe jamais juste. L’étape suivante montre que c’est <b>impossible</b> : aucune fraction n’a pour carré 2.</p></div>
<p>Il manque donc des nombres à ℚ. L’ensemble ℝ des <b>réels</b> est construit pour combler ces trous. Dans ce chapitre, on ne le construit pas : on énonce les <b>règles</b> qu’il respecte, et tout le reste s’en déduit.</p>`,
   fig:(()=>{ const P=plane({x:[-0.4,2.6],y:[-0.4,1.6],h:214,grid:false,axes:false});
     P.poly([[0,0],[1,0],[1,1],[0,1]],{c:'var(--ink)',w:2,fill:'var(--accent)',fo:.12}); P.seg(0,0,1,1,{c:'var(--bad)',w:3});
     P.text(0.5,0,'1',{a:'middle',dy:16,c:'var(--muted)'}).text(1,0.5,'1',{dx:6,dy:5,c:'var(--muted)'}).text(0.5,0.5,'d = √2',{dx:-14,dy:-10,c:'var(--bad)'});
     P.arrow(0,-0.3,2.5,-0.3,{c:'var(--muted)',w:1.5,hs:8}); [0,1,2].forEach(k=>{ P.seg(k,-0.36,k,-0.24,{c:'var(--muted)',w:1.5}); P.text(k,-0.3,String(k),{a:'middle',dy:16,c:'var(--muted)',s:11}); });
     P.seg(0,0,0,-0.3,{c:'var(--muted)',w:1,dash:true}); P.circ(0,-0.3,sq2,{c:'var(--bad)',w:1.5,dash:true}); P.dot(sq2,-0.3,{c:'var(--bad)',r:5,l:'√2'});
     return P.svg(); })(),
   note:'Reporter la diagonale sur l’axe avec un compas donne un point précis de la droite. Ce point ne porte aucune étiquette rationnelle.'},
  {kind:'Théorie',h:'√2 n’est pas rationnel',
   p:`<p>Voici la première grande preuve d’impossibilité de l’analyse. Elle utilise le raisonnement par l’absurde et un résultat sur la parité vu dans la partie « Le langage des ensembles ».</p>
<div class="blk" data-t="Rappel"><p>Si <i>n</i>² est pair, alors <i>n</i> est pair. (Par contraposée : <i>n</i> impair s’écrit 2<i>k</i> + 1 et <i>n</i>² = 2(2<i>k</i>² + 2<i>k</i>) + 1 est impair.)</p></div>
<div class="thm"><p>Il n’existe aucun rationnel <i>r</i> tel que <i>r</i>² = 2.</p></div>
<div class="why"><p>Supposons le contraire : <i>r</i> = <i>p</i>/<i>q</i> avec <i>p</i>, <i>q</i> entiers, <i>q</i> ≠ 0, et la fraction <b>irréductible</b>. Alors <i>p</i>² = 2<i>q</i>². Donc <i>p</i>² est pair, donc <i>p</i> est pair : <i>p</i> = 2<i>k</i>. En remplaçant : 4<i>k</i>² = 2<i>q</i>², soit <i>q</i>² = 2<i>k</i>². Donc <i>q</i>² est pair, donc <i>q</i> est pair. Mais alors <i>p</i> et <i>q</i> sont tous deux divisibles par 2, ce qui contredit l’irréductibilité. L’hypothèse de départ est donc fausse.</p></div>
<div class="idea"><p>Le moteur de la preuve : l’équation <i>p</i>² = 2<i>q</i>² fait rebondir la parité de <i>p</i> sur <i>q</i>, puis le facteur 2 ne s’épuise jamais. Le même argument montre que √3, √5 ou √6 ne sont pas rationnels : il suffit de remplacer « pair » par « divisible par 3 », etc.</p></div>
<div class="warn"><p>L’hypothèse « fraction irréductible » n’est pas décorative. Sans elle, « <i>p</i> et <i>q</i> sont pairs » ne contredit rien.</p></div>`},
  {h:'Le pas décisif',p:'Dans la preuve que √2 est irrationnel, on arrive à <i>p</i>² = 2<i>q</i>². Quelle est la conclusion correcte à ce stade&nbsp;?',
   opts:['<i>p</i> = 2<i>q</i>, donc la fraction se simplifie','<i>p</i>² est pair, donc <i>p</i> est pair','<i>q</i> est pair, puisque 2 divise le membre de droite','<i>p</i> est impair, car un carré pair n’existe pas'],ans:1,
   why:'2q² est un multiple de 2, donc p² est pair. Le résultat « n² pair ⇒ n pair » donne alors p pair. On ne peut pas prendre de racine carrée pour écrire p = 2q : p² = 2q² n’implique pas p = 2q (sinon p² = 4q²).'},
  {kind:'Théorie',h:'Rappel : ce qu’est un corps commutatif',
   p:`<p>Avant de parler d’ordre, fixons ce que les réels partagent avec ℚ : les règles du calcul algébrique. Elles ont été étudiées dans la partie « Anneaux et corps ».</p>
<div class="def"><p>Un <b>corps commutatif</b> est un ensemble <i>K</i> muni de deux opérations + et × telles que :</p><ul><li>(<i>K</i>, +) est un groupe commutatif : + est associative, commutative, a un neutre 0, et tout <i>a</i> a un opposé −<i>a</i> ;</li><li>(<i>K</i> \\ {0}, ×) est un groupe commutatif : × est associative, commutative, a un neutre 1 ≠ 0, et tout <i>a</i> ≠ 0 a un inverse <i>a</i><sup>−1</sup> = 1/<i>a</i> ;</li><li>× est distributive sur + : <i>a</i>(<i>b</i> + <i>c</i>) = <i>ab</i> + <i>ac</i>.</li></ul></div>
<div class="idea"><p>Un corps, c’est un endroit où l’on sait additionner, soustraire, multiplier et diviser par tout ce qui n’est pas nul, avec les règles habituelles. ℚ et ℝ sont des corps commutatifs ; ℤ ne l’est pas (1/2 ∉ ℤ) ; ℤ/7ℤ l’est.</p></div>
<div class="ex"><p>Conséquences déjà démontrées à partir de ces axiomes, valables dans tout corps : <i>a</i> · 0 = 0 ; (−<i>a</i>)(−<i>b</i>) = <i>ab</i> ; si <i>ab</i> = 0, alors <i>a</i> = 0 ou <i>b</i> = 0 ; l’équation <i>ax</i> = <i>b</i> avec <i>a</i> ≠ 0 a l’unique solution <i>x</i> = <i>b</i>/<i>a</i>.</p></div>
<p>Ces axiomes ne disent rien de « plus grand » ou « plus petit ». Pour comparer des réels, il faut une structure supplémentaire : l’ordre.</p>`},
  {kind:'Théorie',h:'Les axiomes d’un corps commutatif ordonné',
   p:`<p>Sur ℝ, on sait comparer : 2 &lt; 3, −5 &lt; 1. Ce qui rend ce « ≤ » utile, c’est qu’il s’entend bien avec les opérations.</p>
<div class="blk" data-t="Rappel"><p>Une relation d’<b>ordre total</b> ≤ sur <i>K</i> est réflexive (<i>a</i> ≤ <i>a</i>), antisymétrique (<i>a</i> ≤ <i>b</i> et <i>b</i> ≤ <i>a</i> ⇒ <i>a</i> = <i>b</i>), transitive, et deux éléments sont toujours comparables. On note <i>a</i> &lt; <i>b</i> pour « <i>a</i> ≤ <i>b</i> et <i>a</i> ≠ <i>b</i> ».</p></div>
<div class="def"><p>Un corps commutatif <i>K</i> muni d’un ordre total ≤ est un <b>corps commutatif ordonné</b> si, pour tous <i>a</i>, <i>b</i>, <i>c</i> de <i>K</i> :</p><ul><li><b>(O1)</b> <i>a</i> ≤ <i>b</i> ⇒ <i>a</i> + <i>c</i> ≤ <i>b</i> + <i>c</i> (compatibilité avec l’addition) ;</li><li><b>(O2)</b> <i>a</i> ≤ <i>b</i> et 0 ≤ <i>c</i> ⇒ <i>ac</i> ≤ <i>bc</i> (compatibilité avec la multiplication par un élément positif).</li></ul></div>
<div class="idea"><p>(O1) dit qu’un décalage conserve l’ordre : si Anne est plus petite que Bob, ils le restent tous deux montés sur la même marche. (O2) dit qu’un agrandissement d’un facteur positif conserve l’ordre. Rien n’est dit sur la multiplication par un négatif : on le <b>déduira</b>.</p></div>
<div class="ex"><p>Dans ℝ : −2 ≤ 5 et 3 ≥ 0 donnent (−2) · 3 ≤ 5 · 3, soit −6 ≤ 15. Les éléments <i>x</i> tels que 0 ≤ <i>x</i> sont dits <b>positifs</b>, ceux tels que <i>x</i> ≤ 0 <b>négatifs</b> ; 0 est les deux à la fois.</p></div>
<p>ℚ et ℝ sont des corps commutatifs ordonnés. Toutes les règles sur les inégalités que tu connais sont des <b>théorèmes</b> déduits de (O1) et (O2).</p>`},
  {kind:'Théorie',h:'Multiplier une inégalité par un nombre',
   p:`<p>La figure place <i>a</i> et <i>b</i> sur l’axe, puis <i>ac</i> et <i>bc</i>. Fais varier <i>c</i> et observe le sens de l’inégalité entre <i>ac</i> et <i>bc</i>.</p>
<div class="prop"><p>Soit <i>a</i> ≤ <i>b</i>. Si <i>c</i> ≥ 0, alors <i>ac</i> ≤ <i>bc</i>. Si <i>c</i> ≤ 0, alors <i>ac</i> ≥ <i>bc</i> : <b>multiplier par un nombre négatif renverse l’inégalité</b>. Si <i>c</i> = 0, les deux produits valent 0.</p></div>
<div class="idea"><p>Multiplier par −1 est une symétrie de l’axe par rapport à 0 : ce qui était à gauche passe à droite. Multiplier par <i>c</i> &lt; 0, c’est agrandir d’un facteur |<i>c</i>| puis appliquer cette symétrie. Le premier geste conserve l’ordre, le second le renverse.</p></div>
<div class="ex"><p>3 ≤ 5 et <i>c</i> = −2 : on obtient −6 et −10, et bien sûr −6 ≥ −10. L’inégalité s’est retournée.</p></div>
<p>La preuve rigoureuse de cette règle, à partir des seuls axiomes, fait l’objet de la méthode qui suit.</p>`,
   params:[{id:'a',l:'a',min:-3,max:3,step:0.5,v:1},{id:'b',l:'b',min:-3,max:3,step:0.5,v:2},{id:'c',l:'c',min:-2,max:2,step:0.5,v:1.5}],
   draw:v=>{ const P=axe([-6.5,6.5],{h:150}); const lo=Math.min(v.a,v.b), hi=Math.max(v.a,v.b);
     P.seg(lo,0.55,hi,0.55,{c:'var(--muted)',w:3}); P.dot(v.a,0.55,{c:'var(--accent)',r:6,l:'a',dy:-10}); P.dot(v.b,0.55,{c:'var(--spark)',r:6,l:'b',dy:-10});
     const pa=v.a*v.c, pb=v.b*v.c; P.seg(Math.min(pa,pb),-0.55,Math.max(pa,pb),-0.55,{c:'var(--muted)',w:3});
     P.dot(pa,-0.55,{c:'var(--accent)',r:6,l:'ac',dy:22,dx:-6}); P.dot(pb,-0.55,{c:'var(--spark)',r:6,l:'bc',dy:22,dx:-6});
     return P.svg(); },
   info:v=>{ const pa=v.a*v.c, pb=v.b*v.c, rel=v.a<v.b?'&lt;':v.a>v.b?'&gt;':'='; const rel2=pa<pb?'&lt;':pa>pb?'&gt;':'=';
     return `<i>a</i> = ${fmt(v.a)} ${rel} <i>b</i> = ${fmt(v.b)} et <i>c</i> = ${fmt(v.c)} : <i>ac</i> = ${fmt(pa)} ${rel2} <i>bc</i> = ${fmt(pb)}. ${v.c<0&&v.a!==v.b?'<b>Le sens a changé.</b>':v.c===0?'Tout s’écrase sur 0.':'Le sens est conservé.'}`; }},
  {kind:'Méthode',h:'Déduire une règle d’inégalité des axiomes',
   p:'<p><b>Quand :</b> on veut justifier une règle de calcul sur les inégalités sans « c’est bien connu ». <b>Pourquoi ça marche :</b> on n’a droit qu’à (O1), (O2) et aux règles du corps ; chaque ligne cite l’axiome utilisé. <b>Comment :</b></p><ol><li>pour changer de membre un terme, ajoute son opposé des deux côtés avec (O1) ;</li><li>pour multiplier, assure-toi que le facteur est positif avant d’utiliser (O2) ; si le facteur est négatif, travaille avec son opposé, qui est positif ;</li><li>simplifie avec les règles du corps (opposé, associativité).</li></ol>',
   demo:{enonce:'Montre que <i>a</i> ≤ <i>b</i> et <i>c</i> ≤ 0 entraînent <i>bc</i> ≤ <i>ac</i>.',
    etapes:[{f:'De <i>c</i> ≤ 0, par (O1) avec le terme −<i>c</i> : <i>c</i> + (−<i>c</i>) ≤ 0 + (−<i>c</i>), soit 0 ≤ −<i>c</i>.',w:'On fait passer c de l’autre côté : l’opposé d’un négatif est positif.'},
     {f:'De <i>a</i> ≤ <i>b</i> et 0 ≤ −<i>c</i>, par (O2) : <i>a</i>(−<i>c</i>) ≤ <i>b</i>(−<i>c</i>), soit −<i>ac</i> ≤ −<i>bc</i>.',w:'(O2) ne s’applique qu’avec un facteur positif : −c en est un.'},
     {f:'Par (O1), on ajoute <i>ac</i> + <i>bc</i> aux deux membres : <i>bc</i> ≤ <i>ac</i>.',w:'−ac + ac + bc = bc à gauche, −bc + ac + bc = ac à droite.'}],
    conclusion:'Multiplier par <i>c</i> ≤ 0 renverse l’inégalité : <b><i>bc</i> ≤ <i>ac</i></b>. Avec <i>c</i> = −1, on obtient en particulier <i>a</i> ≤ <i>b</i> ⇒ −<i>b</i> ≤ −<i>a</i>.'},
   note:'Même recette pour « <i>a</i> ≤ <i>b</i> et <i>c</i> ≤ <i>d</i> ⇒ <i>a</i> + <i>c</i> ≤ <i>b</i> + <i>d</i> » : (O1) deux fois, puis la transitivité de ≤.'},
  {h:'Quelle ligne est permise ?',p:'On sait que <i>x</i> ≤ <i>y</i> et que <i>z</i> ≤ 0. Laquelle de ces déductions est <b>correctement justifiée</b> par un axiome&nbsp;?',
   opts:['<i>xz</i> ≤ <i>yz</i> par (O2)','<i>x</i> − <i>z</i> ≤ <i>y</i> − <i>z</i> par (O1)','<i>x</i>/<i>z</i> ≤ <i>y</i>/<i>z</i> par (O2)','<i>x</i>² ≤ <i>y</i>² par (O2)'],ans:1,
   why:'(O1) autorise à ajouter le même nombre, ici −z, des deux côtés. (O2) exige un facteur positif : z ≤ 0 ne convient pas, et 1/z est aussi négatif. Pour x² ≤ y², il faudrait x et y positifs : −3 ≤ 2 mais 9 > 4.'},
  {kind:'Théorie',h:'Premières conséquences : carrés, 1 et inverses',
   p:`<p>Trois faits que l’on utilise sans y penser se déduisent des axiomes. Ils montrent aussi que tous les corps ne peuvent pas être ordonnés.</p>
<div class="prop"><p>Dans un corps commutatif ordonné :</p><ul><li>pour tout <i>a</i>, <i>a</i>² ≥ 0, et <i>a</i>² = 0 seulement si <i>a</i> = 0 ;</li><li>0 &lt; 1 ;</li><li>si <i>a</i> &gt; 0, alors 1/<i>a</i> &gt; 0 ; si 0 &lt; <i>a</i> ≤ <i>b</i>, alors 1/<i>b</i> ≤ 1/<i>a</i>.</li></ul></div>
<div class="why"><p>Si <i>a</i> ≥ 0, (O2) avec <i>c</i> = <i>a</i> donne <i>a</i> · <i>a</i> ≥ 0 · <i>a</i> = 0. Si <i>a</i> ≤ 0, alors −<i>a</i> ≥ 0 et <i>a</i>² = (−<i>a</i>)² ≥ 0. Ensuite 1 = 1² ≥ 0 et 1 ≠ 0, donc 0 &lt; 1. Enfin, si <i>a</i> &gt; 0 et 1/<i>a</i> ≤ 0, alors (O2) avec le facteur <i>a</i> donnerait <i>a</i> · (1/<i>a</i>) ≤ 0, soit 1 ≤ 0, absurde. Pour la dernière règle, multiplie 0 &lt; <i>a</i> ≤ <i>b</i> par le facteur positif 1/(<i>ab</i>).</p></div>
<div class="ex"><p>De 0 &lt; 1, on tire 1 &lt; 1 + 1 = 2 par (O1), puis 2 &lt; 3, etc. Un corps ordonné contient donc une copie de ℕ, avec 1 + 1 + … + 1 jamais nul.</p></div>
<div class="warn"><p>Dans ℤ/5ℤ, 1 + 1 + 1 + 1 + 1 = 0 : aucun ordre compatible n’est possible, bien que ce soit un corps. L’ordre est une vraie structure supplémentaire, pas une décoration.</p></div>`},
  {h:'Renverser avec soin',p:'Quel est le plus petit réel <i>x</i> qui vérifie 7 − 2<i>x</i> ≤ 1&nbsp;?',lab:'x =',ans:3,
   why:'Par (O1), on ajoute −7 : −2x ≤ −6. On multiplie par −1/2 &lt; 0, ce qui renverse le sens : x ≥ 3. Le plus petit réel solution est x = 3.'},
  {kind:'Théorie',h:'La valeur absolue',
   p:`<p>Sur l’axe, « la distance de <i>x</i> à 0 » doit être un nombre positif, que <i>x</i> soit à gauche ou à droite. C’est le rôle de la valeur absolue.</p>
<div class="def"><p>La <b>valeur absolue</b> de <i>x</i> est |<i>x</i>| = <i>x</i> si <i>x</i> ≥ 0, et |<i>x</i>| = −<i>x</i> si <i>x</i> &lt; 0. Autrement dit, |<i>x</i>| = max(<i>x</i>, −<i>x</i>). Le nombre |<i>x</i> − <i>y</i>| est la <b>distance</b> entre <i>x</i> et <i>y</i>.</p></div>
<div class="prop"><p>Pour tous réels <i>x</i>, <i>y</i> et tout <i>r</i> ≥ 0 :</p><ul><li>|<i>x</i>| ≥ 0, et |<i>x</i>| = 0 ⇔ <i>x</i> = 0 ;</li><li>|<i>xy</i>| = |<i>x</i>| · |<i>y</i>| et |−<i>x</i>| = |<i>x</i>| ;</li><li><b>|<i>x</i>| ≤ <i>r</i> ⇔ −<i>r</i> ≤ <i>x</i> ≤ <i>r</i></b> (de même avec des inégalités strictes).</li></ul></div>
<div class="why"><p>Pour la dernière : |<i>x</i>| ≤ <i>r</i> signifie que <i>x</i> ≤ <i>r</i> <b>et</b> −<i>x</i> ≤ <i>r</i>, puisque |<i>x</i>| est le plus grand des deux. Et −<i>x</i> ≤ <i>r</i> équivaut à −<i>r</i> ≤ <i>x</i> en multipliant par −1. Pour le produit, on examine les quatre cas de signes.</p></div>
<div class="ex"><p>|−3| = 3, |2 − 7| = |−5| = 5 : la distance de 2 à 7 vaut 5. L’inéquation |<i>x</i>| &lt; 2 signifie −2 &lt; <i>x</i> &lt; 2 : les réels à moins de 2 de l’origine.</p></div>
<div class="warn"><p>|<i>x</i>| n’est pas « <i>x</i> sans son signe » quand <i>x</i> est une lettre : √(<i>x</i>²) = |<i>x</i>|, pas <i>x</i>. Pour <i>x</i> = −4, √16 = 4 = |−4|.</p></div>`},
  {kind:'Théorie',h:'L’inégalité triangulaire',
   p:`<p>Comment majorer la valeur absolue d’une somme quand on ne connaît que celles des deux termes ? C’est l’outil numéro un de toute l’analyse.</p>
<div class="thm"><p>Pour tous réels <i>x</i> et <i>y</i> : <b>|<i>x</i> + <i>y</i>| ≤ |<i>x</i>| + |<i>y</i>|</b>, avec égalité exactement quand <i>x</i> et <i>y</i> sont de même signe (ou l’un est nul). De plus, <b>| |<i>x</i>| − |<i>y</i>| | ≤ |<i>x</i> − <i>y</i>|</b>.</p></div>
<div class="why"><p>Par définition, <i>x</i> ≤ |<i>x</i>| et <i>y</i> ≤ |<i>y</i>| ; en additionnant (O1 deux fois), <i>x</i> + <i>y</i> ≤ |<i>x</i>| + |<i>y</i>|. De même −<i>x</i> ≤ |<i>x</i>| et −<i>y</i> ≤ |<i>y</i>| donnent −(<i>x</i> + <i>y</i>) ≤ |<i>x</i>| + |<i>y</i>|. Le plus grand des deux nombres <i>x</i> + <i>y</i> et −(<i>x</i> + <i>y</i>) est |<i>x</i> + <i>y</i>| : d’où le résultat. Pour la seconde, écris <i>x</i> = (<i>x</i> − <i>y</i>) + <i>y</i> : |<i>x</i>| ≤ |<i>x</i> − <i>y</i>| + |<i>y</i>|, donc |<i>x</i>| − |<i>y</i>| ≤ |<i>x</i> − <i>y</i>| ; échange les rôles pour l’autre sens.</p></div>
<div class="ex"><p><i>x</i> = 5, <i>y</i> = −3 : |5 + (−3)| = 2, alors que |5| + |−3| = 8. Signes opposés : inégalité stricte. Avec <i>x</i> = 5, <i>y</i> = 3 : 8 = 8, égalité.</p></div>
<div class="idea"><p>Le nom vient de la géométrie : un côté d’un triangle est plus court que la somme des deux autres. Sur une droite, les « triangles » sont plats, mais l’inégalité reste vraie. Sous la forme |<i>a</i> − <i>c</i>| ≤ |<i>a</i> − <i>b</i>| + |<i>b</i> − <i>c</i>|, elle dit qu’un détour par <i>b</i> n’est jamais plus court que le trajet direct.</p></div>`},
  {kind:'Pratique',h:'Quand l’inégalité est stricte',p:'La barre du haut montre |<i>x</i>| + |<i>y</i>|, celle du bas |<i>x</i> + <i>y</i>|. Choisis <i>x</i> et <i>y</i> non nuls pour que l’inégalité triangulaire soit <b>stricte</b>, avec un écart |<i>x</i>| + |<i>y</i>| − |<i>x</i> + <i>y</i>| égal à <b>exactement 4</b>.',
   params:[{id:'x',l:'x',min:-4,max:4,step:0.5,v:3},{id:'y',l:'y',min:-4,max:4,step:0.5,v:1}],
   draw:v=>{ const P=plane({x:[-0.5,9],y:[-0.3,2.3],h:110,grid:false,axes:false}); const s1=Math.abs(v.x)+Math.abs(v.y), s2=Math.abs(v.x+v.y);
     P.rect(0,1.3,Math.abs(v.x),0.6,{fill:'var(--accent)',fo:.6,c:null}).rect(Math.abs(v.x),1.3,Math.abs(v.y),0.6,{fill:'var(--spark)',fo:.6,c:null});
     P.rect(0,0.2,s2,0.6,{fill:'var(--ok)',fo:.6,c:null}); P.seg(0,0,0,2.2,{c:'var(--muted)',w:1.5});
     P.text(s1,1.6,'|x| + |y| = '+fmt(s1),{dx:6,dy:5}).text(s2,0.5,'|x + y| = '+fmt(s2),{dx:6,dy:5}); return P.svg(); },
   info:v=>`Écart : ${fmt(Math.abs(v.x)+Math.abs(v.y)-Math.abs(v.x+v.y))}.`,
   ok:v=>v.x!==0&&v.y!==0&&Math.abs(Math.abs(v.x)+Math.abs(v.y)-Math.abs(v.x+v.y)-4)<1e-9,
   why:'L’écart n’est non nul que si x et y sont de signes opposés ; il vaut alors 2 · min(|x|, |y|). Pour un écart de 4, le plus petit des deux en valeur absolue doit valoir 2 : par exemple x = 3 et y = −2, ou x = −2 et y = 4.'},
  {kind:'Méthode',h:'Résoudre une inéquation avec une valeur absolue',
   p:'<p><b>Quand :</b> l’inconnue est sous une valeur absolue : |2<i>x</i> − 1| ≤ 5, |<i>x</i> − 3| &gt; 2. <b>Pourquoi ça marche :</b> |<i>u</i>| ≤ <i>r</i> équivaut au double encadrement −<i>r</i> ≤ <i>u</i> ≤ <i>r</i>, et |<i>u</i>| &gt; <i>r</i> à « <i>u</i> &lt; −<i>r</i> ou <i>u</i> &gt; <i>r</i> ». <b>Comment :</b></p><ol><li>isole la valeur absolue d’un côté ;</li><li>traduis-la en encadrement (≤, &lt;) ou en alternative (≥, &gt;) ;</li><li>résous chaque inégalité avec (O1) et (O2), en renversant le sens si tu multiplies par un négatif.</li></ol>',
   demo:{enonce:'Résous |2<i>x</i> − 1| ≤ 5 dans ℝ.',
    etapes:[{f:'|2<i>x</i> − 1| ≤ 5 ⇔ −5 ≤ 2<i>x</i> − 1 ≤ 5.',w:'La règle |u| ≤ r ⇔ −r ≤ u ≤ r, avec u = 2x − 1.'},
     {f:'⇔ −4 ≤ 2<i>x</i> ≤ 6.',w:'(O1) : on ajoute 1 aux trois membres.'},
     {f:'⇔ −2 ≤ <i>x</i> ≤ 3.',w:'(O2) : on multiplie par 1/2 &gt; 0, le sens est conservé.'}],
    conclusion:'Les solutions sont les réels <i>x</i> avec <b>−2 ≤ <i>x</i> ≤ 3</b>. Lecture géométrique : |2<i>x</i> − 1| = 2|<i>x</i> − 1/2|, donc on cherche les <i>x</i> à distance au plus 5/2 de 1/2.'},
   note:'Pour |<i>x</i> − 3| &gt; 2 : <i>x</i> − 3 &lt; −2 ou <i>x</i> − 3 &gt; 2, soit <i>x</i> &lt; 1 ou <i>x</i> &gt; 5. Les deux morceaux ne se recollent pas.'},
  {h:'Longueur de l’ensemble des solutions',p:'On résout |3<i>x</i> + 2| &lt; 7. Les solutions forment un segment de l’axe (bornes exclues). Quelle est sa longueur ? Donne une fraction ou arrondis au centième.',lab:'longueur =',ans:14/3,tol:0.01,
   why:'−7 &lt; 3x + 2 &lt; 7 ⇔ −9 &lt; 3x &lt; 5 ⇔ −3 &lt; x &lt; 5/3. Longueur : 5/3 − (−3) = 14/3 ≈ 4,67.'},
  {kind:'Récapitulatif',h:'Ce qu’il faut retenir',
   p:`<p>Ce chapitre pose les règles du jeu sur ℝ. Tout ce qui suit dans l’analyse s’appuie dessus.</p>
<div class="keep"><ul><li>√2 n’est pas rationnel : preuve par l’absurde avec une fraction irréductible et la parité (<i>p</i>² = 2<i>q</i>²).</li><li>Un <b>corps commutatif</b> : deux opérations, toutes les règles du calcul, division par tout élément non nul.</li><li><b>Corps ordonné</b> : ordre total compatible avec + (O1) et avec la multiplication par un positif (O2).</li><li>Conséquences : multiplier par un négatif renverse l’inégalité ; <i>a</i>² ≥ 0 ; 0 &lt; 1 ; 0 &lt; <i>a</i> ≤ <i>b</i> ⇒ 1/<i>b</i> ≤ 1/<i>a</i>.</li><li><b>Valeur absolue</b> : |<i>x</i>| = max(<i>x</i>, −<i>x</i>) ; |<i>x</i> − <i>y</i>| est une distance ; |<i>x</i>| ≤ <i>r</i> ⇔ −<i>r</i> ≤ <i>x</i> ≤ <i>r</i>.</li><li><b>Inégalité triangulaire</b> : |<i>x</i> + <i>y</i>| ≤ |<i>x</i>| + |<i>y</i>| ; égalité si même signe.</li><li>Méthodes : déduire une règle des axiomes (citer O1, O2) ; résoudre |<i>u</i>| ≤ <i>r</i> par un double encadrement.</li></ul></div>`},
  {kind:'Problème',h:'√3 est irrationnel',
   p:'On veut adapter la preuve de l’irrationalité de √2 au nombre √3, défini comme un réel positif dont le carré vaut 3. On suppose √3 = <i>p</i>/<i>q</i> avec <i>p</i>, <i>q</i> entiers naturels non nuls et la fraction irréductible, puis on cherche une contradiction. Le rôle de la parité est joué par la divisibilité par 3, et il faut d’abord s’assurer du résultat « si 3 divise <i>n</i>², alors 3 divise <i>n</i> ».',
   parts:[
    {q:'a) Un entier <i>n</i> non divisible par 3 s’écrit 3<i>k</i> + 1 ou 3<i>k</i> + 2. Quel est le reste de (3<i>k</i> + 2)² dans la division par 3&nbsp;?',lab:'reste :',ans:1,hint:'Développe (3k + 2)² et isole les multiples de 3.',why:'(3k + 2)² = 9k² + 12k + 4 = 3(3k² + 4k + 1) + 1 : le reste est 1. De même (3k + 1)² = 3(3k² + 2k) + 1.'},
    {q:'b) Qu’en déduit-on&nbsp;?',opts:['Si <i>n</i> n’est pas divisible par 3, <i>n</i>² ne l’est pas non plus ; par contraposée, 3 | <i>n</i>² ⇒ 3 | <i>n</i>','Tout carré a pour reste 1 modulo 3','Si 3 divise <i>n</i>, alors 3 divise <i>n</i>²','3 ne divise jamais un carré'],ans:0,hint:'On a traité les deux cas « non divisible par 3 ». C’est une preuve par contraposée.',why:'Dans les deux cas, n² a pour reste 1 : il n’est pas divisible par 3. La contraposée dit exactement : 3 | n² ⇒ 3 | n. L’option 3 est vraie mais ne sert pas ici.'},
    {q:'c) De √3 = <i>p</i>/<i>q</i>, on tire <i>p</i>² = 3<i>q</i>², donc 3 | <i>p</i>, et on écrit <i>p</i> = 3<i>k</i>. Que devient l’équation&nbsp;?',opts:['<i>q</i>² = 9<i>k</i>²','3<i>k</i>² = <i>q</i>²','<i>q</i>² = 3<i>k</i>','<i>k</i>² = 3<i>q</i>²'],ans:1,hint:'Remplace p par 3k dans p² = 3q² puis divise par 3.',why:'(3k)² = 9k² = 3q², et en divisant par 3 : q² = 3k². Donc 3 divise q², donc 3 divise q : p et q sont tous deux multiples de 3, contradiction avec l’irréductibilité.'},
    {q:'d) La même méthode prouve que √<i>m</i> est irrationnel pour <i>m</i> = 5, 6, 7. Pour lequel de ces entiers échoue-t-elle (et pour cause)&nbsp;?',opts:['<i>m</i> = 6','<i>m</i> = 9','<i>m</i> = 7','<i>m</i> = 5'],ans:1,hint:'Pour quel m existe-t-il visiblement une fraction (ou un entier) dont le carré vaut m ?',why:'√9 = 3 est rationnel, donc aucune preuve ne peut aboutir : l’argument « 9 | n² ⇒ 9 | n » est d’ailleurs faux (n = 3). Pour 5, 6, 7, le raisonnement fonctionne avec un diviseur premier bien choisi.'},
   ],
   sol:'Supposons √3 = <i>p</i>/<i>q</i> irréductible. Alors <i>p</i>² = 3<i>q</i>² est divisible par 3. Or un entier non multiple de 3 s’écrit 3<i>k</i> + 1 ou 3<i>k</i> + 2, et son carré a pour reste 1 : donc 3 | <i>p</i>² entraîne 3 | <i>p</i>. On écrit <i>p</i> = 3<i>k</i> : 9<i>k</i>² = 3<i>q</i>², soit <i>q</i>² = 3<i>k</i>², et pour la même raison 3 | <i>q</i>. La fraction <i>p</i>/<i>q</i> se simplifie par 3 : contradiction. <b>√3 est irrationnel.</b> La méthode marche pour tout entier qui n’est pas un carré parfait, en s’appuyant sur un facteur premier ; elle échoue, à juste titre, pour 9.'},
  {kind:'Problème',h:'Moyenne arithmétique et moyenne géométrique',
   p:'Pour deux réels positifs <i>a</i> et <i>b</i>, la <b>moyenne arithmétique</b> est (<i>a</i> + <i>b</i>)/2 et la <b>moyenne géométrique</b> est √(<i>ab</i>). On veut prouver que la seconde ne dépasse jamais la première, en utilisant seulement que le carré d’un réel est positif, et savoir quand elles sont égales. On admet que tout réel positif <i>t</i> a une racine carrée √<i>t</i> ≥ 0 (ce sera démontré au chapitre suivant).',
   parts:[
    {q:'a) Pour <i>a</i> = 2 et <i>b</i> = 8, calcule la différence (<i>a</i> + <i>b</i>)/2 − √(<i>ab</i>).',lab:'différence =',ans:1,hint:'√16 = 4.',why:'(2 + 8)/2 = 5 et √(2 · 8) = √16 = 4 : la différence vaut 1.'},
    {q:'b) Quelle quantité, positive d’après le chapitre, permet de démarrer la preuve&nbsp;?',opts:['(<i>a</i> − <i>b</i>)²','(√<i>a</i> − √<i>b</i>)²','<i>a</i>² + <i>b</i>²','√<i>a</i> · √<i>b</i>'],ans:1,hint:'En développant, il faut voir apparaître a, b et √(ab).',why:'(√a − √b)² = a − 2√(ab) + b ≥ 0 car c’est un carré. Donc a + b ≥ 2√(ab), puis (a + b)/2 ≥ √(ab) en multipliant par 1/2 &gt; 0.'},
    {q:'c) Quand a-t-on égalité des deux moyennes&nbsp;?',opts:['Jamais','Quand <i>a</i> = <i>b</i>','Quand <i>ab</i> = 1','Quand <i>a</i> + <i>b</i> = 2'],ans:1,hint:'Un carré est nul seulement si sa base est nulle.',why:'L’égalité a lieu si (√a − √b)² = 0, c’est-à-dire √a = √b, donc a = b.'},
    {q:'d) Un rectangle a un périmètre de 20 cm. Quelle est la plus grande aire possible, en cm²&nbsp;?',unit:'cm²',ans:25,hint:'Côtés a et b avec a + b = 10 ; l’aire est ab = (√(ab))².',why:'(a + b)/2 = 5 ≥ √(ab), donc ab ≤ 25, avec égalité pour a = b = 5 : le carré de côté 5 cm a l’aire maximale 25 cm².'},
   ],
   sol:'Soient <i>a</i>, <i>b</i> ≥ 0. Le réel (√<i>a</i> − √<i>b</i>)² est un carré, donc positif : <i>a</i> − 2√<i>a</i>√<i>b</i> + <i>b</i> ≥ 0, soit <i>a</i> + <i>b</i> ≥ 2√(<i>ab</i>). En multipliant par 1/2 &gt; 0 (axiome O2) : <b>(<i>a</i> + <i>b</i>)/2 ≥ √(<i>ab</i>)</b>. L’égalité exige (√<i>a</i> − √<i>b</i>)² = 0, donc <i>a</i> = <i>b</i>. Pour <i>a</i> = 2, <i>b</i> = 8 : 5 ≥ 4. Application : si <i>a</i> + <i>b</i> = 10, alors √(<i>ab</i>) ≤ 5 et <i>ab</i> ≤ 25 ; l’aire maximale d’un rectangle de périmètre 20 est 25 cm², atteinte par le carré.'},
]},
/* ===================== 2. BORNE SUPÉRIEURE ET CONTINUITÉ DE ℝ ===================== */
{subj:'gred',sem:'ana',id:'gred-borne-sup',h:'Borne supérieure et continuité de ℝ',p:'Majorants, maximum, borne supérieure, et l’axiome qui distingue ℝ de ℚ : toute partie non vide majorée a une borne supérieure. Conséquences : Archimède, densité de ℚ, existence de √2.',steps:[
  {kind:'Théorie',h:'Majorant, minorant, partie bornée',
   p:`<p>Une partie de ℝ peut « monter sans fin » (comme ℕ) ou rester sous un plafond (comme les 1/<i>n</i>). Le vocabulaire des bornes, vu pour les ordres en général, prend tout son sens sur ℝ.</p>
<div class="def"><p>Soit <i>A</i> ⊂ ℝ. Un réel <i>M</i> est un <b>majorant</b> de <i>A</i> si <i>a</i> ≤ <i>M</i> pour tout <i>a</i> ∈ <i>A</i>. Un réel <i>m</i> est un <b>minorant</b> si <i>m</i> ≤ <i>a</i> pour tout <i>a</i> ∈ <i>A</i>. <i>A</i> est <b>majorée</b> si elle a un majorant, <b>minorée</b> si elle a un minorant, <b>bornée</b> si elle est les deux.</p></div>
<div class="idea"><p>Un majorant est un plafond : tout <i>A</i> est en dessous ou au niveau. Il n’a aucune raison d’appartenir à <i>A</i>, et s’il en existe un, il en existe une infinité (tout nombre plus grand convient aussi).</p></div>
<div class="ex"><p><i>A</i> = {1/<i>n</i> : <i>n</i> ∈ ℕ*} = {1, 1/2, 1/3, …}. Majorants : 1, 2, 100, tout réel ≥ 1. Minorants : 0, −3, tout réel ≤ 0. <i>A</i> est bornée. En revanche ℕ est minorée (par 0) mais pas majorée ; ℤ n’est ni l’un ni l’autre.</p></div>
<div class="warn"><p>« <i>A</i> est bornée » équivaut à : il existe <i>K</i> ≥ 0 tel que |<i>a</i>| ≤ <i>K</i> pour tout <i>a</i> ∈ <i>A</i>. Une seule constante suffit : prends <i>K</i> = max(|<i>m</i>|, |<i>M</i>|).</p></div>`},
  {kind:'Théorie',h:'Maximum ou borne supérieure ?',
   p:`<p>Parmi tous les majorants d’une partie, un seul est intéressant : le plus bas. Il remplace la notion de « plus grand élément » quand celle-ci fait défaut.</p>
<div class="def"><p>Soit <i>A</i> ⊂ ℝ non vide. Le <b>maximum</b> de <i>A</i>, noté max <i>A</i>, est un élément de <i>A</i> qui majore <i>A</i>. La <b>borne supérieure</b> de <i>A</i>, notée sup <i>A</i>, est le <b>plus petit des majorants</b> de <i>A</i>. De même, min <i>A</i> et la <b>borne inférieure</b> inf <i>A</i>, le plus grand des minorants.</p></div>
<div class="idea"><p>Le maximum doit être <b>dans</b> <i>A</i>. La borne supérieure, non : elle est le point exact où s’arrêtent les plafonds. Si <i>A</i> a un maximum, alors sup <i>A</i> = max <i>A</i>. Mais une partie peut avoir une borne supérieure sans maximum.</p></div>
<div class="ex"><p><i>A</i> = ]0 ; 1[ (les réels strictement entre 0 et 1). Pas de maximum : si <i>a</i> ∈ <i>A</i>, alors (<i>a</i> + 1)/2 est encore dans <i>A</i> et plus grand. Pourtant 1 est un majorant, et aucun réel <i>M</i> &lt; 1 n’en est un (si 0 &lt; <i>M</i> &lt; 1, (<i>M</i> + 1)/2 ∈ <i>A</i> le dépasse). Donc <b>sup <i>A</i> = 1</b>, et 1 ∉ <i>A</i>. De même inf <i>A</i> = 0. Pour <i>B</i> = {1/<i>n</i>} : max <i>B</i> = 1 = sup <i>B</i>, inf <i>B</i> = 0 et <i>B</i> n’a pas de minimum.</p></div>
<div class="why"><p>La borne supérieure, quand elle existe, est unique : deux plus petits majorants se majorent l’un l’autre, donc sont égaux (antisymétrie).</p></div>`,
   fig:(()=>{ const P=axe([-0.6,2.2],{h:150,step:1}); inter(P,0,1,false,false,{y:0.55}); P.text(1,0.55,'sup = 1 ∉ A',{dx:10,dy:4,c:'var(--accent)'}).text(0,0.55,'A = ]0 ; 1[',{a:'end',dx:-10,dy:4,c:'var(--muted)'});
     for(let n=1;n<=12;n++) P.dot(1/n,-0.55,{r:4,c:'var(--spark)'}); P.text(1,-0.55,'max B = 1',{dx:10,dy:4,c:'var(--spark)'}); P.text(0,-0.55,'inf B = 0 ∉ B',{a:'end',dx:-10,dy:4,c:'var(--muted)'});
     return P.svg(); })()},
  {kind:'Pratique',h:'Trouve la borne supérieure',p:'Les points sont les éléments de <i>A</i> = {1 − 1/<i>n</i> : <i>n</i> ∈ ℕ*} = {0, 1/2, 2/3, 3/4, …}. Place <i>M</i> pour qu’il soit un majorant de <i>A</i>, mais que <b>aucun réel plus petit</b> n’en soit un : <i>M</i> = sup <i>A</i>.',
   params:[{id:'M',l:'M',min:0.5,max:1.5,step:0.05,v:1.2}],
   draw:v=>{ const P=axe([-0.3,1.7],{h:120,step:0.5}); for(let n=1;n<=40;n++) P.dot(1-1/n,0,{r:3.5,c:'var(--accent)'});
     P.seg(v.M,-0.45,v.M,0.45,{c:1-1/40<=v.M+1e-9?'var(--ok)':'var(--bad)',w:3}); P.text(v.M,0.45,'M',{a:'middle',dy:-6}); return P.svg(); },
   info:v=>{ const maj=v.M>=1-1e-9; let s=maj?'<i>M</i> est un majorant.':'<i>M</i> n’est pas un majorant : des points le dépassent (prends <i>n</i> assez grand).';
     if(maj&&v.M>1+1e-9) s+=' Mais '+fmt(v.M-0.05)+' en est un aussi : ce n’est pas le plus petit.'; return s; },
   ok:v=>Math.abs(v.M-1)<1e-9,
   why:'Tous les 1 − 1/n sont &lt; 1, donc 1 majore A. Si M &lt; 1, il existe n avec 1/n &lt; 1 − M, donc 1 − 1/n &gt; M : M ne majore pas. Ainsi sup A = 1, et 1 ∉ A : pas de maximum.'},
  {h:'Max, sup, ou rien ?',p:'Soit <i>A</i> = {(−1)<sup><i>n</i></sup>/<i>n</i> : <i>n</i> ∈ ℕ*} = {−1, 1/2, −1/3, 1/4, …}. Laquelle de ces affirmations est vraie&nbsp;?',
   opts:['sup <i>A</i> = 1 et <i>A</i> n’a pas de maximum','max <i>A</i> = 1/2 et min <i>A</i> = −1','sup <i>A</i> = 1/2 mais <i>A</i> n’a pas de maximum','<i>A</i> n’est pas majorée'],ans:1,
   why:'Les termes positifs sont 1/2, 1/4, 1/6, … : le plus grand est 1/2, atteint pour n = 2. Les négatifs sont −1, −1/3, −1/5, … : le plus petit est −1, atteint pour n = 1. A a donc un maximum et un minimum.'},
  {kind:'Méthode',h:'Prouver qu’un nombre est la borne supérieure',
   p:'<p><b>Quand :</b> on devine sup <i>A</i> = <i>s</i> et on doit le justifier. <b>Pourquoi ça marche :</b> « plus petit majorant » se traduit en deux conditions vérifiables : (1) <i>s</i> majore <i>A</i> ; (2) aucun nombre plus petit ne majore <i>A</i>, c’est-à-dire : <b>pour tout ε &gt; 0, il existe <i>a</i> ∈ <i>A</i> avec <i>a</i> &gt; <i>s</i> − ε</b>. <b>Comment :</b></p><ol><li>montre <i>a</i> ≤ <i>s</i> pour tout <i>a</i> ∈ <i>A</i> (souvent une inégalité directe) ;</li><li>fixe ε &gt; 0 et <b>construis</b> un élément de <i>A</i> au-dessus de <i>s</i> − ε (souvent en résolvant une inéquation en <i>n</i>) ;</li><li>précise si <i>s</i> ∈ <i>A</i> (alors c’est un maximum) ou non.</li></ol>',
   demo:{enonce:'Montre que sup <i>A</i> = 2 pour <i>A</i> = {2 − 3/<i>n</i> : <i>n</i> ∈ ℕ*}.',
    etapes:[{f:'Pour tout <i>n</i> ≥ 1, 3/<i>n</i> &gt; 0, donc 2 − 3/<i>n</i> &lt; 2 : 2 est un majorant.',w:'Condition (1), et au passage 2 ∉ A.'},
     {f:'Soit ε &gt; 0. On cherche <i>n</i> avec 2 − 3/<i>n</i> &gt; 2 − ε, c’est-à-dire 3/<i>n</i> &lt; ε, soit <i>n</i> &gt; 3/ε.',w:'On traduit « dépasser s − ε » en inéquation sur n.'},
     {f:'Un tel entier <i>n</i> existe (par exemple le premier entier qui dépasse 3/ε). Pour ε = 0,01, <i>n</i> = 301 donne 2 − 3/301 ≈ 1,990 &gt; 1,99.',w:'Condition (2) : aucun 2 − ε n’est un majorant.'}],
    conclusion:'<b>sup <i>A</i> = 2</b>, et ce n’est pas un maximum. Par ailleurs, les termes croissent avec <i>n</i>, donc min <i>A</i> = inf <i>A</i> = 2 − 3 = −1.'},
   note:'L’existence d’un entier n &gt; 3/ε semble évidente. C’est la propriété d’Archimède, démontrée un peu plus loin.'},
  {h:'Une borne supérieure à calculer',p:'Soit <i>A</i> = {5 − 4/(<i>n</i> + 1) : <i>n</i> ∈ ℕ}. Que vaut sup <i>A</i>&nbsp;?',lab:'sup A =',ans:5,
   why:'4/(n + 1) &gt; 0, donc tous les éléments sont &lt; 5. Pour ε &gt; 0, 4/(n + 1) &lt; ε dès que n + 1 &gt; 4/ε : un élément dépasse 5 − ε. Donc sup A = 5 (non atteint). Le minimum est 5 − 4 = 1, pour n = 0.'},
  {kind:'Théorie',h:'L’axiome de la borne supérieure',
   p:`<p>Dans ℚ, la partie <i>A</i> = {<i>x</i> ∈ ℚ : <i>x</i> ≥ 0 et <i>x</i>² &lt; 2} est non vide et majorée (par 2). A-t-elle une borne supérieure <b>dans ℚ</b> ? Non : son plafond exact devrait être √2, qui n’est pas rationnel. ℚ a des trous ; ℝ est précisément le corps qui n’en a pas.</p>
<div class="thm"><p><b>Axiome de la borne supérieure.</b> Toute partie de ℝ <b>non vide et majorée</b> admet une borne supérieure dans ℝ. On dit que ℝ est un corps commutatif ordonné <b>continu</b> (ou complet).</p></div>
<div class="prop"><p>Par symétrie, toute partie non vide et <b>minorée</b> admet une borne inférieure : si <i>A</i> est minorée, −<i>A</i> = {−<i>a</i> : <i>a</i> ∈ <i>A</i>} est majorée, et inf <i>A</i> = −sup(−<i>A</i>).</p></div>
<div class="idea"><p>C’est un axiome : on ne le démontre pas, on le pose comme propriété définissant ℝ (toute construction de ℝ, par coupures ou par suites de Cauchy, a pour but de le réaliser). Il dit que si une partie est bloquée par un plafond, il existe un plafond <b>exact</b>, un réel qui la touche sans la dépasser. Tous les théorèmes d’existence de l’analyse (limites, valeurs intermédiaires, maxima) en descendent.</p></div>
<div class="warn"><p>Les deux hypothèses sont indispensables : ∅ n’a pas de borne supérieure (tout réel la majore, il n’y a pas de plus petit), et ℕ non plus (pas de majorant du tout).</p></div>
<div class="ex"><p><i>A</i> = {<i>x</i> ∈ ℝ : <i>x</i>³ &lt; 10}. Non vide (0 ∈ <i>A</i>), majorée par 3 (si <i>x</i> ≥ 3, <i>x</i>³ ≥ 27). L’axiome garantit l’existence de sup <i>A</i>, un réel qu’on appellera ∛10, sans avoir besoin de l’écrire.</p></div>`},
  {kind:'Théorie',h:'La propriété d’Archimède',
   p:`<p>Il n’existe pas de réel « infiniment grand », plus grand que tous les entiers. Cela paraît évident ; c’est pourtant un théorème, et il se déduit de l’axiome de la borne supérieure.</p>
<div class="thm"><p><b>Archimède.</b> ℕ n’est pas majoré dans ℝ : pour tout réel <i>x</i>, il existe un entier <i>n</i> tel que <i>n</i> &gt; <i>x</i>. Formes équivalentes : pour tout ε &gt; 0, il existe <i>n</i> ∈ ℕ* avec 1/<i>n</i> &lt; ε ; pour tous <i>a</i> &gt; 0 et <i>b</i>, il existe <i>n</i> avec <i>na</i> &gt; <i>b</i>.</p></div>
<div class="why"><p>Par l’absurde : si ℕ était majoré, il aurait (non vide, majoré) une borne supérieure <i>s</i>. Alors <i>s</i> − 1 n’est pas un majorant : il existe <i>n</i> ∈ ℕ avec <i>n</i> &gt; <i>s</i> − 1. Mais alors <i>n</i> + 1 ∈ ℕ et <i>n</i> + 1 &gt; <i>s</i> : <i>s</i> ne majore pas ℕ. Contradiction. Pour la deuxième forme, applique la première à <i>x</i> = 1/ε, puis inverse (0 &lt; 1/ε &lt; <i>n</i> ⇒ 1/<i>n</i> &lt; ε).</p></div>
<div class="idea"><p>Aussi petit que soit un pas ε &gt; 0, en le répétant assez de fois on dépasse n’importe quelle distance. C’est la propriété qui fait tendre 1/<i>n</i> vers 0 : elle sera invoquée dans presque toutes les preuves de limite.</p></div>
<div class="ex"><p>ε = 0,003 : 1/ε ≈ 333,3, donc <i>n</i> = 334 convient (1/334 ≈ 0,002994 &lt; 0,003), et aucun <i>n</i> ≤ 333 ne convient.</p></div>
<div class="blk" data-t="Remarque"><p>Il existe des corps ordonnés non archimédiens, contenant des « infiniment grands ». Ils ne vérifient pas l’axiome de la borne supérieure, ce qui confirme que celui-ci est plus fort.</p></div>`},
  {kind:'Pratique',h:'Le premier entier qui convient',p:'Pour ε = 0,15, trouve le <b>plus petit</b> entier <i>n</i> ≥ 1 tel que 1/<i>n</i> &lt; ε. Les points sont les valeurs 1/<i>k</i> ; la bande montre les réels inférieurs à ε.',
   params:[{id:'n',l:'n',min:1,max:20,v:3}],
   draw:v=>{ const P=plane({x:[-0.5,21],y:[-0.08,1.1],h:200,grid:false,lx:5,ly:0.25}); P.rect(-0.5,-0.08,21.5,0.23,{fill:'var(--ok)',fo:.15,c:null}); P.seg(-0.5,0.15,21,0.15,{c:'var(--ok)',w:1.5,dash:true});
     for(let k=1;k<=20;k++) P.dot(k,1/k,{r:k===v.n?6:3.5,c:k===v.n?'var(--spark)':'var(--accent)'}); P.text(21,0.15,'ε',{a:'end',dy:-5,c:'var(--ok)'}); return P.svg(); },
   info:v=>`1/${v.n} ≈ ${fmt(1/v.n,3)} ${1/v.n<0.15?'&lt; 0,15 : ça marche.':'≥ 0,15 : pas encore.'}`,
   ok:v=>v.n===7,why:'1/n &lt; 0,15 ⇔ n &gt; 1/0,15 ≈ 6,67. Le premier entier est n = 7 (1/7 ≈ 0,143), alors que 1/6 ≈ 0,167 dépasse ε.'},
  {kind:'Théorie',h:'ℚ est dense dans ℝ',
   p:`<p>ℚ a des trous, mais il est partout : entre deux réels distincts, si proches soient-ils, il y a toujours une fraction.</p>
<div class="thm"><p><b>Densité de ℚ.</b> Pour tous réels <i>a</i> &lt; <i>b</i>, il existe un rationnel <i>r</i> tel que <i>a</i> &lt; <i>r</i> &lt; <i>b</i>. Il en existe alors une infinité.</p></div>
<div class="why"><p>Par Archimède, on choisit <i>n</i> ∈ ℕ* avec 1/<i>n</i> &lt; <i>b</i> − <i>a</i> : les multiples de 1/<i>n</i> forment une grille de pas plus petit que l’intervalle, donc l’un d’eux tombe dedans. Précisément, soit <i>m</i> le plus petit entier tel que <i>m</i> &gt; <i>na</i> (il existe par Archimède, et par la propriété du plus petit élément de ℕ). Alors <i>m</i> − 1 ≤ <i>na</i>, donc <i>m</i> ≤ <i>na</i> + 1 &lt; <i>na</i> + <i>n</i>(<i>b</i> − <i>a</i>) = <i>nb</i>. Ainsi <i>na</i> &lt; <i>m</i> &lt; <i>nb</i>, et <i>r</i> = <i>m</i>/<i>n</i> convient. En recommençant entre <i>a</i> et <i>r</i>, on en trouve autant qu’on veut.</p></div>
<div class="ex"><p><i>a</i> = 0,71, <i>b</i> = 0,72 : <i>b</i> − <i>a</i> = 0,01, on prend <i>n</i> = 101 (1/101 &lt; 0,01). <i>na</i> = 71,71, donc <i>m</i> = 72 et <i>r</i> = 72/101 ≈ 0,7129. Vérification : 0,71 &lt; 0,7129 &lt; 0,72.</p></div>
<div class="blk" data-t="Remarque"><p>Les irrationnels aussi sont denses : entre <i>a</i> et <i>b</i>, prends un rationnel <i>r</i> entre <i>a</i> − √2 et <i>b</i> − √2 ; alors <i>r</i> + √2 est irrationnel (sinon √2 = (<i>r</i> + √2) − <i>r</i> serait rationnel) et il est entre <i>a</i> et <i>b</i>.</p></div>`},
  {h:'Une fraction entre deux décimaux',p:'On applique la preuve de la densité à <i>a</i> = 2,345 et <i>b</i> = 2,347, avec <i>n</i> = 501. Quel est l’entier <i>m</i> fourni par la preuve (le plus petit entier strictement supérieur à <i>na</i>)&nbsp;?',lab:'m =',ans:1175,
   why:'na = 501 · 2,345 = 1174,845, donc m = 1175. Et m/n = 1175/501 ≈ 2,3453, bien compris entre 2,345 et 2,347.'},
  {kind:'Théorie',h:'√2 existe dans ℝ',
   p:`<p>Au chapitre précédent, on a vu qu’aucune fraction n’a pour carré 2. L’axiome de la borne supérieure fournit enfin un réel qui le fait.</p>
<div class="thm"><p>Il existe un unique réel <i>s</i> &gt; 0 tel que <i>s</i>² = 2. On le note √2. Plus généralement, tout réel <i>t</i> ≥ 0 a une unique racine carrée positive.</p></div>
<div class="why"><p>Soit <i>A</i> = {<i>x</i> ∈ ℝ : <i>x</i> ≥ 0 et <i>x</i>² &lt; 2}. <i>A</i> est non vide (1 ∈ <i>A</i>) et majorée par 2 (si <i>x</i> ≥ 2, <i>x</i>² ≥ 4). Soit <i>s</i> = sup <i>A</i> ; on montre <i>s</i>² = 2 en éliminant les deux autres cas. Si <i>s</i>² &lt; 2 : pour <i>h</i> ∈ ]0 ; 1[, (<i>s</i> + <i>h</i>)² = <i>s</i>² + <i>h</i>(2<i>s</i> + <i>h</i>) ≤ <i>s</i>² + <i>h</i>(2<i>s</i> + 1), qui est &lt; 2 dès que <i>h</i> &lt; (2 − <i>s</i>²)/(2<i>s</i> + 1) ; alors <i>s</i> + <i>h</i> ∈ <i>A</i> dépasse <i>s</i>, impossible. Si <i>s</i>² &gt; 2 : (<i>s</i> − <i>h</i>)² ≥ <i>s</i>² − 2<i>sh</i> &gt; 2 pour <i>h</i> petit, donc <i>s</i> − <i>h</i> majore <i>A</i> (tout <i>x</i> ≥ <i>s</i> − <i>h</i> a un carré &gt; 2), contredisant « plus petit majorant ». Reste <i>s</i>² = 2. L’unicité vient de : 0 &lt; <i>s</i> &lt; <i>s</i>′ ⇒ <i>s</i>² &lt; <i>s</i>′².</p></div>
<div class="idea"><p>On ne « calcule » pas √2 : on le capture comme le plafond exact des réels positifs de carré inférieur à 2. C’est le schéma de toutes les preuves d’existence par borne supérieure : nommer la bonne partie, prendre son sup, montrer qu’il ne peut être ni trop petit ni trop grand.</p></div>
<div class="ex"><p>1,4 ∈ <i>A</i> (1,96 &lt; 2), 1,41 ∈ <i>A</i> (1,9881), 1,415 ∉ <i>A</i> (2,002225). Le sup est coincé entre 1,41 et 1,415.</p></div>`},
  {kind:'Théorie',h:'Le panorama ℕ ⊂ ℤ ⊂ ℚ ⊂ ℝ',
   p:`<p>Chaque extension des nombres a été motivée par une opération impossible dans l’ensemble précédent. Voici le bilan.</p>
<div class="blk" data-t="Vue d’ensemble"><ul><li><b>ℕ</b> = {0, 1, 2, …} : on compte. Toute partie non vide a un plus petit élément. Mais 3 − 5 n’existe pas.</li><li><b>ℤ</b> : on ajoute les opposés ; (ℤ, +) est un groupe, (ℤ, +, ×) un anneau intègre. Mais 1/2 n’existe pas.</li><li><b>ℚ</b> : corps des fractions de ℤ ; un corps commutatif ordonné, archimédien, dense. Mais √2 n’existe pas : des parties majorées sans borne supérieure.</li><li><b>ℝ</b> : corps commutatif ordonné <b>continu</b> ; toute partie non vide majorée a un sup. Les éléments de ℝ \\ ℚ sont les <b>irrationnels</b> (√2, π, …).</li></ul></div>
<div class="idea"><p>De ℕ à ℚ, on ajoute des solutions d’équations (<i>x</i> + 5 = 3, 2<i>x</i> = 1). De ℚ à ℝ, on change de nature : on ajoute des <b>limites</b>, des plafonds exacts. C’est pourquoi l’analyse commence vraiment avec ℝ.</p></div>
<div class="ex"><p>Classement de quelques nombres : −7 ∈ ℤ \\ ℕ ; 0,75 = 3/4 ∈ ℚ \\ ℤ ; √9 = 3 ∈ ℕ ; √3 ∈ ℝ \\ ℚ ; 0,333… = 1/3 ∈ ℚ.</p></div>
<div class="warn"><p>Un nombre à développement décimal infini n’est pas forcément irrationnel : 1/3 = 0,333… est rationnel. Ce sont les développements infinis <b>non périodiques</b> qui sont irrationnels (ce sera vu plus loin).</p></div>`,
   fig:(()=>{ const P=plane({x:[0,8],y:[0,5],h:200,grid:false,axes:false}); const b=[[0.2,0.2,7.6,4.6,'ℝ','var(--math)'],[0.6,0.6,5.6,3.6,'ℚ','var(--accent)'],[1,1,3.6,2.6,'ℤ','var(--spark)'],[1.4,1.4,1.8,1.6,'ℕ','var(--ok)']];
     b.forEach(([x,y,w,h,l,c])=>{ P.rect(x,y,w,h,{c,w:2,fill:c,fo:.1}); P.text(x+w,y+h,l,{a:'end',dx:-8,dy:18,c}); });
     P.text(1.6,2.1,'0, 1, 2',{s:12}).text(3.2,3.2,'−7',{s:12}).text(5,3.8,'3/4',{s:12}).text(6.8,1,'√2, π',{s:12,a:'end'}); return P.svg(); })()},
  {h:'Vrai dans ℝ, faux dans ℚ',p:'Laquelle de ces propriétés est vraie dans ℝ mais <b>fausse</b> dans ℚ&nbsp;?',
   opts:['Entre deux éléments distincts, il y en a toujours un troisième','Toute partie non vide majorée a une borne supérieure dans l’ensemble','Pour tout <i>x</i>, il existe un entier <i>n</i> &gt; <i>x</i>','Tout élément non nul a un inverse'],ans:1,
   why:'ℚ est dense, archimédien et c’est un corps : les options 1, 3 et 4 y sont vraies. Seul l’axiome de la borne supérieure échoue dans ℚ : {x ∈ ℚ : x² &lt; 2} est majorée sans borne supérieure rationnelle.'},
  {kind:'Récapitulatif',h:'Ce qu’il faut retenir',
   p:`<p>La borne supérieure est l’outil qui distingue ℝ de ℚ et qui fonde toute l’analyse.</p>
<div class="keep"><ul><li><b>Majorant</b> : <i>M</i> ≥ tout élément de <i>A</i>. <b>Borné</b> = majoré et minoré (⇔ |<i>a</i>| ≤ <i>K</i>).</li><li><b>max <i>A</i></b> : un majorant qui appartient à <i>A</i>. <b>sup <i>A</i></b> : le plus petit majorant ; il peut ne pas appartenir à <i>A</i> (]0 ; 1[ : sup = 1, pas de max).</li><li>Caractérisation : <i>s</i> = sup <i>A</i> ⇔ <i>s</i> majore <i>A</i> et ∀ε &gt; 0, ∃<i>a</i> ∈ <i>A</i>, <i>a</i> &gt; <i>s</i> − ε.</li><li><b>Axiome</b> : toute partie de ℝ non vide et majorée a une borne supérieure (ℝ est continu). Faux dans ℚ.</li><li><b>Archimède</b> : ℕ n’est pas majoré ; ∀ε &gt; 0, ∃<i>n</i>, 1/<i>n</i> &lt; ε. Preuve par le sup de ℕ.</li><li><b>Densité</b> : entre deux réels, un rationnel (et un irrationnel). Preuve : grille de pas 1/<i>n</i> &lt; <i>b</i> − <i>a</i>.</li><li><b>√2 existe</b> : sup {<i>x</i> ≥ 0 : <i>x</i>² &lt; 2}, dont le carré ne peut être ni &lt; 2 ni &gt; 2.</li><li>ℕ ⊂ ℤ ⊂ ℚ ⊂ ℝ : opposés, inverses, puis bornes supérieures.</li></ul></div>`},
  {kind:'Problème',h:'Étude complète d’une partie de ℝ',
   p:'On considère <i>A</i> = {<i>a</i><sub><i>n</i></sub> : <i>n</i> ∈ ℕ*} avec <i>a</i><sub><i>n</i></sub> = (−1)<sup><i>n</i></sup> + 1/<i>n</i>. Les premiers éléments sont <i>a</i>₁ = 0, <i>a</i>₂ = 3/2, <i>a</i>₃ = −2/3, <i>a</i>₄ = 5/4. On veut déterminer sup <i>A</i>, inf <i>A</i>, et dire s’il s’agit d’un maximum ou d’un minimum. Sépare les indices pairs (où (−1)<sup><i>n</i></sup> = 1) des indices impairs.',
   fig:(()=>{ const P=suite(n=>(-1)**n+1/n,{n0:1,N:16,y:[-1.4,1.9],h:190,lx:4,ly:0.5}); P.seg(-0.8,-1,17,-1,{c:'var(--bad)',w:1.5,dash:true}); return P.svg(); })(),
   parts:[
    {q:'a) Calcule <i>a</i>₅.',lab:'a₅ =',ans:-0.8,tol:0.001,hint:'n = 5 est impair : (−1)⁵ = −1.',why:'a₅ = −1 + 1/5 = −4/5 = −0,8.'},
    {q:'b) Que vaut sup <i>A</i>&nbsp;?',lab:'sup A =',ans:1.5,tol:0.001,hint:'Les éléments d’indice pair sont 1 + 1/n, décroissants ; ceux d’indice impair sont négatifs.',why:'Pour n pair, aₙ = 1 + 1/n ≤ 1 + 1/2 = 3/2, atteint pour n = 2. Pour n impair, aₙ = −1 + 1/n ≤ 0. Donc sup A = 3/2 = max A.'},
    {q:'c) Et la borne inférieure&nbsp;?',opts:['inf <i>A</i> = −1, et c’est un minimum','inf <i>A</i> = −1, mais <i>A</i> n’a pas de minimum','inf <i>A</i> = −2/3, atteint pour <i>n</i> = 3','<i>A</i> n’est pas minorée'],ans:1,hint:'Pour n impair, aₙ = −1 + 1/n : minore-le, puis montre qu’on s’approche de −1 autant qu’on veut.',why:'Tout aₙ vaut au moins −1 + 1/n &gt; −1 : −1 minore A sans lui appartenir. Pour ε &gt; 0, l’indice impair n &gt; 1/ε donne aₙ = −1 + 1/n &lt; −1 + ε. Donc inf A = −1, non atteint.'},
    {q:'d) Quel est le plus petit indice <i>n</i> tel que <i>a</i><sub><i>n</i></sub> &lt; −0,99&nbsp;?',lab:'n =',ans:101,hint:'Il faut n impair et 1/n &lt; 0,01.',why:'Pour n impair, −1 + 1/n &lt; −0,99 ⇔ 1/n &lt; 0,01 ⇔ n &gt; 100. Le premier impair au-delà de 100 est n = 101.'},
   ],
   sol:'Si <i>n</i> est pair, <i>a</i><sub><i>n</i></sub> = 1 + 1/<i>n</i> : ces éléments décroissent de 3/2 (pour <i>n</i> = 2) vers 1. Si <i>n</i> est impair, <i>a</i><sub><i>n</i></sub> = −1 + 1/<i>n</i> : ils décroissent de 0 (pour <i>n</i> = 1) vers −1 en restant strictement au-dessus de −1. Donc <b>sup <i>A</i> = max <i>A</i> = 3/2</b>. Pour la borne inférieure, −1 est un minorant (tout élément dépasse −1 ou vaut au moins 1) et, pour ε &gt; 0, un indice impair <i>n</i> &gt; 1/ε donne un élément en dessous de −1 + ε : <b>inf <i>A</i> = −1</b>, non atteint, donc pas de minimum. Pour <i>a</i><sub><i>n</i></sub> &lt; −0,99 il faut <i>n</i> impair et <i>n</i> &gt; 100 : <i>n</i> = 101.'},
  {kind:'Problème',h:'La borne supérieure d’une somme',
   p:'Soient <i>A</i> et <i>B</i> deux parties non vides majorées de ℝ. On note <i>A</i> + <i>B</i> = {<i>a</i> + <i>b</i> : <i>a</i> ∈ <i>A</i>, <i>b</i> ∈ <i>B</i>}. On veut prouver que <i>A</i> + <i>B</i> est majorée et que <b>sup(<i>A</i> + <i>B</i>) = sup <i>A</i> + sup <i>B</i></b>, en suivant la méthode de caractérisation de la borne supérieure. On teste ensuite sur <i>A</i> = ]0 ; 1[ et <i>B</i> = {1 − 1/<i>n</i> : <i>n</i> ∈ ℕ*}.',
   parts:[
    {q:'a) Pour <i>A</i> = ]0 ; 1[ et <i>B</i> = {1 − 1/<i>n</i>}, que vaut sup <i>A</i> + sup <i>B</i>&nbsp;?',lab:'somme =',ans:2,hint:'Les deux bornes supérieures ont été calculées dans le chapitre.',why:'sup A = 1 et sup B = 1, donc la somme vaut 2. Aucun élément de A + B n’atteint 2.'},
    {q:'b) Notons <i>s</i> = sup <i>A</i> et <i>t</i> = sup <i>B</i>. Pourquoi <i>s</i> + <i>t</i> majore-t-il <i>A</i> + <i>B</i>&nbsp;?',opts:['Parce que <i>s</i> + <i>t</i> appartient à <i>A</i> + <i>B</i>','Pour tout <i>a</i> ∈ <i>A</i> et <i>b</i> ∈ <i>B</i>, <i>a</i> ≤ <i>s</i> et <i>b</i> ≤ <i>t</i>, donc <i>a</i> + <i>b</i> ≤ <i>s</i> + <i>t</i> par (O1) deux fois','Parce que sup(<i>A</i> + <i>B</i>) existe par l’axiome','Parce que <i>A</i> et <i>B</i> sont bornées'],ans:1,hint:'Un élément de A + B s’écrit a + b. Majore chaque morceau.',why:'a ≤ s et b ≤ t donnent a + b ≤ s + b ≤ s + t. C’est la condition (1) de la méthode : s + t est un majorant, donc sup(A + B) ≤ s + t.'},
    {q:'c) Soit ε &gt; 0. Pour montrer qu’aucun nombre plus petit que <i>s</i> + <i>t</i> ne majore <i>A</i> + <i>B</i>, on choisit <i>a</i> ∈ <i>A</i> et <i>b</i> ∈ <i>B</i> tels que…',opts:['<i>a</i> &gt; <i>s</i> − ε et <i>b</i> &gt; <i>t</i> − ε, d’où <i>a</i> + <i>b</i> &gt; <i>s</i> + <i>t</i> − ε','<i>a</i> &gt; <i>s</i> − ε/2 et <i>b</i> &gt; <i>t</i> − ε/2, d’où <i>a</i> + <i>b</i> &gt; <i>s</i> + <i>t</i> − ε','<i>a</i> = <i>s</i> et <i>b</i> = <i>t</i>','<i>a</i> + <i>b</i> = <i>s</i> + <i>t</i> − ε'],ans:1,hint:'Chaque borne supérieure fournit un élément à moins de « quelque chose » : partage ε en deux.',why:'La caractérisation de s donne a &gt; s − ε/2, celle de t donne b &gt; t − ε/2 ; en sommant, a + b &gt; s + t − ε. Avec ε entier (option 1), on obtiendrait seulement s + t − 2ε, ce qui est plus faible mais pas faux ; l’option 3 suppose que les sup sont atteints.'},
    {q:'d) Dans l’exemple, pour ε = 0,1, donne un élément de <i>B</i> strictement supérieur à <i>t</i> − ε/2 = 0,95 sous la forme 1 − 1/<i>n</i> : quel est le plus petit <i>n</i> qui convient&nbsp;?',lab:'n =',ans:21,hint:'1 − 1/n &gt; 0,95 ⇔ 1/n &lt; 0,05.',why:'1/n &lt; 0,05 ⇔ n &gt; 20, donc n = 21 : 1 − 1/21 ≈ 0,952. Avec a = 0,96 ∈ A, a + b ≈ 1,912 &gt; 2 − 0,1.'},
   ],
   sol:'Notons <i>s</i> = sup <i>A</i>, <i>t</i> = sup <i>B</i>. (1) Pour <i>a</i> ∈ <i>A</i>, <i>b</i> ∈ <i>B</i> : <i>a</i> ≤ <i>s</i> et <i>b</i> ≤ <i>t</i>, donc <i>a</i> + <i>b</i> ≤ <i>s</i> + <i>t</i> ; <i>A</i> + <i>B</i> est majorée par <i>s</i> + <i>t</i>, et par l’axiome sa borne supérieure existe et vérifie sup(<i>A</i> + <i>B</i>) ≤ <i>s</i> + <i>t</i>. (2) Soit ε &gt; 0. Par caractérisation des bornes supérieures, il existe <i>a</i> ∈ <i>A</i> avec <i>a</i> &gt; <i>s</i> − ε/2 et <i>b</i> ∈ <i>B</i> avec <i>b</i> &gt; <i>t</i> − ε/2 ; alors <i>a</i> + <i>b</i> ∈ <i>A</i> + <i>B</i> et <i>a</i> + <i>b</i> &gt; <i>s</i> + <i>t</i> − ε. Aucun réel inférieur à <i>s</i> + <i>t</i> ne majore donc <i>A</i> + <i>B</i> : <b>sup(<i>A</i> + <i>B</i>) = sup <i>A</i> + sup <i>B</i></b>. Exemple : <i>A</i> = ]0 ; 1[, <i>B</i> = {1 − 1/<i>n</i>} : sup(<i>A</i> + <i>B</i>) = 2, non atteint.'},
]},
/* ===================== 3. DROITE RÉELLE, INTERVALLES ET VOISINAGES ===================== */
{subj:'gred',sem:'ana',id:'gred-intervalles',h:'Droite réelle, intervalles et voisinages',p:'Les réels vus comme des points d’une droite : les neuf types d’intervalles, les intervalles emboîtés, et la notion de voisinage qui prépare les limites.',steps:[
  {kind:'Théorie',h:'La droite réelle',
   p:`<p>Les axiomes de ℝ sont abstraits. Pour raisonner, on a besoin d’une image : une droite sur laquelle chaque réel est un point.</p>
<div class="def"><p>On choisit sur une droite un point <i>O</i> (l’<b>origine</b>, image de 0) et un point <i>I</i> (image de 1), qui fixe l’unité et le sens positif. À tout réel <i>x</i> correspond alors un unique point <i>M</i> tel que la longueur <i>OM</i> vaille |<i>x</i>|, du côté de <i>I</i> si <i>x</i> &gt; 0, de l’autre côté sinon. Cette correspondance est une <b>bijection</b> entre ℝ et la droite, qu’on appelle la <b>droite réelle</b> ; <i>x</i> est l’<b>abscisse</b> de <i>M</i>.</p></div>
<div class="idea"><p>L’ordre devient géométrique : <i>a</i> &lt; <i>b</i> signifie « <i>a</i> est à gauche de <i>b</i> ». La distance entre les points d’abscisses <i>a</i> et <i>b</i> est |<i>b</i> − <i>a</i>|. Que la correspondance soit <b>bijective</b>, c’est-à-dire que la droite n’ait aucun trou, traduit exactement l’axiome de la borne supérieure : ℚ, lui, laisserait des points sans abscisse (celui de la diagonale du carré unité, par exemple).</p></div>
<div class="ex"><p>Les points d’abscisses −2 et 3,5 sont distants de |3,5 − (−2)| = 5,5. Le milieu du segment qui les joint a pour abscisse (−2 + 3,5)/2 = 0,75.</p></div>
<div class="warn"><p>La figure ne remplace pas la preuve : on ne « voit » pas si un point est rationnel ou non. Mais elle guide l’intuition, et toutes les définitions qui suivent (intervalle, voisinage) se lisent dessus.</p></div>`,
   fig:(()=>{ const P=axe([-3.5,4.5],{h:110}); P.dot(0,0,{c:'var(--ink)',r:5,l:'O',dy:-12}); P.dot(1,0,{c:'var(--ink)',r:5,l:'I',dy:-12}); P.dot(-2,0,{c:'var(--accent)',r:6,l:'−2',dy:-12}); P.dot(3.5,0,{c:'var(--spark)',r:6,l:'3,5',dy:-12}); P.dot(sq2,0,{c:'var(--bad)',r:5,l:'√2',dy:-12});
     P.seg(-2,-0.55,3.5,-0.55,{c:'var(--muted)',w:2}); P.text(0.75,-0.55,'|3,5 − (−2)| = 5,5',{a:'middle',dy:18,c:'var(--muted)',s:12}); return P.svg(); })()},
  {kind:'Théorie',h:'Les neuf types d’intervalles',
   p:`<p>Les parties les plus simples de la droite sont les morceaux « d’un seul tenant » : les intervalles. Ils ont une définition par l’ordre, et un catalogue complet.</p>
<div class="def"><p>Une partie <i>I</i> ⊂ ℝ est un <b>intervalle</b> si, dès qu’elle contient deux réels, elle contient tous les réels situés entre eux : pour tous <i>x</i>, <i>y</i> ∈ <i>I</i> et tout <i>z</i> avec <i>x</i> ≤ <i>z</i> ≤ <i>y</i>, on a <i>z</i> ∈ <i>I</i>.</p></div>
<div class="prop"><p>Pour <i>a</i> &lt; <i>b</i>, tout intervalle ayant au moins deux points est de l’un des <b>neuf types</b> du tableau. Un crochet tourné vers l’intérieur ([<i>a</i> ou <i>b</i>]) signifie que la borne est <b>incluse</b> ; tourné vers l’extérieur (]<i>a</i> ou <i>b</i>[), qu’elle est <b>exclue</b>. Les symboles ±∞ ne sont pas des réels : le crochet qui les accompagne est toujours tourné vers l’extérieur.</p></div>
<div class="idea"><p>Pourquoi neuf ? Chaque extrémité est soit un réel inclus, soit un réel exclu, soit infinie : trois choix à gauche, trois à droite. Les cas dégénérés ∅ et {<i>a</i>} = [<i>a</i> ; <i>a</i>] sont aussi des intervalles, mais sans intérêt.</p></div>
<div class="ex"><p>[2 ; 5[ contient 2, 3,99 et 4,999 mais pas 5. ]−∞ ; 0] est l’ensemble des réels négatifs (0 compris). [0 ; +∞[ celui des positifs. ℝ* = ℝ \\ {0} n’est pas un intervalle : il contient −1 et 1 mais pas 0.</p></div>
<div class="why"><p>Pourquoi le tableau est complet : soit <i>I</i> un intervalle ; s’il est majoré, posons <i>b</i> = sup <i>I</i> (axiome), sinon il s’étend jusqu’à +∞ ; de même à gauche avec inf <i>I</i>. Par la définition, tout réel strictement entre inf <i>I</i> et sup <i>I</i> est dans <i>I</i> ; seules les bornes elles-mêmes restent en suspens, d’où les crochets.</p></div>`,
   fig:tab(['Notation','Définition','Nom'],[[TYPES[0].n,TYPES[0].d,'fermé borné (segment)'],[TYPES[1].n,TYPES[1].d,'semi-ouvert'],[TYPES[2].n,TYPES[2].d,'semi-ouvert'],[TYPES[3].n,TYPES[3].d,'ouvert borné'],[TYPES[4].n,TYPES[4].d,'fermé non borné'],[TYPES[5].n,TYPES[5].d,'ouvert non borné'],[TYPES[6].n,TYPES[6].d,'fermé non borné'],[TYPES[7].n,TYPES[7].d,'ouvert non borné'],[TYPES[8].n,TYPES[8].d,'la droite entière']])},
  {kind:'Théorie',h:'Lire un intervalle sur l’axe',
   p:`<p>Choisis un type d’intervalle (avec <i>a</i> = 1 et <i>b</i> = 4) et déplace le point <i>x</i>. La figure dit si <i>x</i> appartient à l’intervalle.</p>
<div class="idea"><p>Sur l’axe, une borne incluse est un point plein, une borne exclue un point creux. Un intervalle infini se prolonge jusqu’au bout de la flèche. Appartenir à l’intervalle, c’est vérifier la double inégalité de sa définition : pour <i>x</i> = 4 et ]1 ; 4[, l’inégalité <i>x</i> &lt; 4 est fausse, donc 4 ∉ ]1 ; 4[, alors que 4 ∈ ]1 ; 4].</p></div>
<div class="ex"><p>Le réel 1 appartient à [1 ; 4], [1 ; 4[, [1 ; +∞[, ]−∞ ; 4], ]−∞ ; 4[ et ℝ, mais pas à ]1 ; 4], ]1 ; 4[ ni ]1 ; +∞[. Le réel 0 n’appartient à aucun intervalle de bornes 1 et 4, mais appartient aux quatre intervalles qui commencent à −∞.</p></div>
<div class="warn"><p>Les notations [<i>a</i> ; <i>b</i>] avec <i>a</i> &gt; <i>b</i> désignent l’ensemble vide : on écrit toujours la plus petite borne à gauche.</p></div>`,
   params:[{id:'t',l:'Type (0 à 8, dans l’ordre du tableau)',min:0,max:8,v:3},{id:'x',l:'x',min:-1,max:6,step:0.5,v:4}],
   draw:v=>{ const T=TYPES[v.t], P=axe([-1.5,6.5],{h:120}); inter(P,T.a,T.b,T.ca,T.cb); const inn=T.t(v.x,1,4); P.dot(v.x,0.5,{c:inn?'var(--ok)':'var(--bad)',r:6,l:'x',dy:-10}); P.seg(v.x,0.5,v.x,0,{c:'var(--muted)',w:1,dash:true}); return P.svg(); },
   info:v=>{ const T=TYPES[v.t]; return `Intervalle <b>${T.n.replace(/<i>a<\/i>/g,'1').replace(/<i>b<\/i>/g,'4')}</b> (${T.d.replace(/<i>a<\/i>/g,'1').replace(/<i>b<\/i>/g,'4')}). <i>x</i> = ${fmt(v.x)} : ${T.t(v.x,1,4)?'<b style="color:var(--ok)">appartient</b>':'<b style="color:var(--bad)">n’appartient pas</b>'} à l’intervalle.`; }},
  {h:'Intervalle ou pas ?',p:'Une seule de ces parties de ℝ est un intervalle. Laquelle&nbsp;?',
   opts:['{<i>x</i> ∈ ℝ : <i>x</i>² ≥ 1}','ℚ ∩ [0 ; 1]','{<i>x</i> ∈ ℝ : <i>x</i>² &lt; 9}','ℝ \\ {2}'],ans:2,
   why:'x² &lt; 9 ⇔ |x| &lt; 3 ⇔ −3 &lt; x &lt; 3 : c’est ]−3 ; 3[. Les autres ont des trous : x² ≥ 1 contient −1 et 1 mais pas 0 ; ℚ ∩ [0 ; 1] contient 0 et 1 mais pas √2/2 ; ℝ \\ {2} contient 1 et 3 mais pas 2.'},
  {kind:'Méthode',h:'Traduire des inégalités en intervalles, intersection et réunion',
   p:'<p><b>Quand :</b> un ensemble est décrit par des inégalités, ou comme intersection ou réunion de deux intervalles, et on veut l’écrire avec des crochets. <b>Pourquoi ça marche :</b> les règles (O1) et (O2) transforment une double inégalité en un encadrement de <i>x</i> ; l’intersection garde les points communs, donc la plus grande des bornes gauches et la plus petite des bornes droites. <b>Comment :</b></p><ol><li>isole <i>x</i> dans chaque inégalité (attention au renversement par un négatif) ;</li><li>dessine les deux intervalles sur un même axe ;</li><li>pour ∩, prends la partie recouverte deux fois ; pour ∪, la partie recouverte au moins une fois ; vérifie chaque borne séparément (incluse si elle est incluse dans les deux pour ∩, dans au moins un pour ∪).</li></ol>',
   demo:{enonce:'Écris <i>E</i> = {<i>x</i> ∈ ℝ : 1 &lt; 2<i>x</i> − 1 ≤ 5} avec des crochets, puis calcule [−1 ; 2[ ∩ ]0 ; 4] et [−1 ; 2[ ∪ ]0 ; 4].',
    etapes:[{f:'1 &lt; 2<i>x</i> − 1 ≤ 5 ⇔ 2 &lt; 2<i>x</i> ≤ 6 ⇔ 1 &lt; <i>x</i> ≤ 3.',w:'(O1) : +1 partout ; (O2) : × 1/2, positif, le sens est conservé.'},
     {f:'<i>E</i> = ]1 ; 3] : 1 exclu (inégalité stricte), 3 inclus.',w:'Chaque crochet recopie le type d’inégalité correspondant.'},
     {f:'[−1 ; 2[ ∩ ]0 ; 4] = ]0 ; 2[ : la borne gauche est la plus grande (0, exclu car exclu dans ]0 ; 4]), la borne droite la plus petite (2, exclu).',w:'Un point commun doit vérifier les deux conditions ; 0 échoue dans le second intervalle, 2 dans le premier.'},
     {f:'[−1 ; 2[ ∪ ]0 ; 4] = [−1 ; 4] : les deux morceaux se chevauchent, la réunion est un intervalle.',w:'−1 est inclus dans le premier, 4 dans le second. Si les intervalles ne se chevauchaient pas, la réunion ne serait pas un intervalle.'}],
    conclusion:'<i>E</i> = ]1 ; 3], l’intersection vaut ]0 ; 2[ et la réunion [−1 ; 4]. Toujours dessiner : les erreurs de crochets se voient sur l’axe.'},
   note:'[2 ; 3] ∪ [5 ; 7] n’est pas un intervalle (4 manque). [2 ; 3[ ∪ [3 ; 5] = [2 ; 5] en est un : les morceaux se touchent exactement.'},
  {h:'Longueur d’une intersection',p:'Quelle est la longueur de l’intervalle [−3 ; 5[ ∩ ]1 ; 9]&nbsp;?',lab:'longueur =',ans:4,
   why:'L’intersection est ]1 ; 5[ : borne gauche max(−3, 1) = 1, borne droite min(5, 9) = 5. Sa longueur est 5 − 1 = 4 (les crochets ne changent pas la longueur).'},
  {kind:'Théorie',h:'Intervalles emboîtés',
   p:`<p>Si l’on resserre un étau de segments les uns dans les autres, reste-t-il toujours quelque chose au centre ? Oui dans ℝ, et c’est encore l’axiome de la borne supérieure qui le garantit.</p>
<div class="def"><p>Une suite d’intervalles (<i>I</i><sub><i>n</i></sub>) est <b>emboîtée</b> (ou décroissante) si <i>I</i><sub>0</sub> ⊃ <i>I</i><sub>1</sub> ⊃ <i>I</i><sub>2</sub> ⊃ … : chaque intervalle contient le suivant.</p></div>
<div class="thm"><p><b>Segments emboîtés.</b> Si <i>I</i><sub><i>n</i></sub> = [<i>a</i><sub><i>n</i></sub> ; <i>b</i><sub><i>n</i></sub>] sont des segments (fermés bornés) emboîtés, alors leur intersection est non vide : il existe un réel qui appartient à tous les <i>I</i><sub><i>n</i></sub>. Si de plus les longueurs <i>b</i><sub><i>n</i></sub> − <i>a</i><sub><i>n</i></sub> deviennent plus petites que tout ε &gt; 0, ce réel est unique.</p></div>
<div class="why"><p>L’emboîtement donne <i>a</i><sub>0</sub> ≤ <i>a</i><sub>1</sub> ≤ … et … ≤ <i>b</i><sub>1</sub> ≤ <i>b</i><sub>0</sub>, et tout <i>a</i><sub><i>n</i></sub> est ≤ tout <i>b</i><sub><i>m</i></sub> (prends l’indice le plus grand des deux). L’ensemble <i>A</i> des <i>a</i><sub><i>n</i></sub> est non vide, majoré par <i>b</i><sub>0</sub> : soit <i>c</i> = sup <i>A</i>. Alors <i>a</i><sub><i>n</i></sub> ≤ <i>c</i> pour tout <i>n</i> (majorant), et <i>c</i> ≤ <i>b</i><sub><i>n</i></sub> pour tout <i>n</i> (chaque <i>b</i><sub><i>n</i></sub> majore <i>A</i>, et <i>c</i> est le plus petit majorant). Donc <i>c</i> ∈ [<i>a</i><sub><i>n</i></sub> ; <i>b</i><sub><i>n</i></sub>] pour tout <i>n</i>.</p></div>
<div class="ex"><p><i>I</i><sub><i>n</i></sub> = [0 ; 1/<i>n</i>] : l’intersection est {0}. <i>I</i><sub><i>n</i></sub> = [1 − 1/<i>n</i> ; 1 + 1/<i>n</i>] : l’intersection est {1}.</p></div>
<div class="warn"><p>Les hypothèses comptent. Avec des intervalles <b>ouverts</b> <i>J</i><sub><i>n</i></sub> = ]0 ; 1/<i>n</i>[, l’intersection est <b>vide</b> : un réel <i>x</i> &gt; 0 sort de <i>J</i><sub><i>n</i></sub> dès que 1/<i>n</i> ≤ <i>x</i> (Archimède). Avec des fermés <b>non bornés</b> <i>K</i><sub><i>n</i></sub> = [<i>n</i> ; +∞[, l’intersection est vide aussi : aucun réel ne dépasse tous les entiers.</p></div>`,
   fig:(()=>{ const P=axe([-0.3,2.3],{h:170,step:1}); const cols=['var(--accent)','var(--spark)','var(--ok)','var(--math)']; [1,2,3,4].forEach((n,i)=>inter(P,1-1/n,1+1/n,true,true,{y:0.75-i*0.4,c:cols[i],w:5}));
     P.text(1,0.75,'I₁',{a:'end',dx:-66,dy:4,c:'var(--muted)',s:11}).text(1,-0.45,'I₄',{a:'end',dx:-66,dy:4,c:'var(--muted)',s:11}); P.seg(1,-0.7,1,1,{c:'var(--bad)',w:1,dash:true}); return P.svg(); })()},
  {h:'Que reste-t-il ?',p:'Pour <i>n</i> ≥ 1, on pose <i>J</i><sub><i>n</i></sub> = ]2 − 1/<i>n</i> ; 2 + 1/<i>n</i>[ (intervalles ouverts). Que vaut l’intersection de tous les <i>J</i><sub><i>n</i></sub>&nbsp;?',
   opts:['∅, car les intervalles sont ouverts','{2}','[2 − 1/<i>n</i> ; 2 + 1/<i>n</i>] pour <i>n</i> très grand','L’intervalle ]1 ; 3['],ans:1,
   why:'2 appartient à chaque Jₙ. Si x ≠ 2, Archimède fournit n avec 1/n &lt; |x − 2|, et alors x ∉ Jₙ. L’intersection est donc {2} : des ouverts emboîtés peuvent avoir une intersection non vide ; le contre-exemple ]0 ; 1/n[ ne marche que parce que le point visé, 0, est au bord.'},
  {kind:'Théorie',h:'Voisinage d’un point',
   p:`<p>Pour parler de limite, on devra dire « <i>x</i> est tout près de <i>a</i> », avec du jeu de chaque côté. Le mot pour ça est <b>voisinage</b>.</p>
<div class="def"><p>Une partie <i>V</i> ⊂ ℝ est un <b>voisinage</b> du réel <i>a</i> s’il existe <i>r</i> &gt; 0 tel que ]<i>a</i> − <i>r</i> ; <i>a</i> + <i>r</i>[ ⊂ <i>V</i>. L’intervalle ]<i>a</i> − <i>r</i> ; <i>a</i> + <i>r</i>[ est lui-même le <b>voisinage ouvert de centre <i>a</i> et de rayon <i>r</i></b>.</p></div>
<div class="idea"><p><i>V</i> est un voisinage de <i>a</i> si <i>a</i> y est « à l’aise » : non seulement <i>a</i> ∈ <i>V</i>, mais il y a de la place autour de lui, des deux côtés, aussi petite soit-elle. Un point au bord d’un intervalle n’est pas à l’aise : d’un côté, il sort tout de suite.</p></div>
<div class="prop"><p>Avec la valeur absolue : <b><i>x</i> ∈ ]<i>a</i> − <i>r</i> ; <i>a</i> + <i>r</i>[ ⇔ |<i>x</i> − <i>a</i>| &lt; <i>r</i></b>. C’est la règle |<i>u</i>| &lt; <i>r</i> ⇔ −<i>r</i> &lt; <i>u</i> &lt; <i>r</i> appliquée à <i>u</i> = <i>x</i> − <i>a</i>. L’intersection de deux voisinages de <i>a</i> est un voisinage de <i>a</i> (prends le plus petit des deux rayons).</p></div>
<div class="ex"><p>[0 ; 1] est un voisinage de 0,5 (rayon 0,5 convient : ]0 ; 1[ ⊂ [0 ; 1]) et de 0,99 (rayon 0,01). Il n’est pas un voisinage de 0 : tout ]−<i>r</i> ; <i>r</i>[ contient des négatifs. ℝ est un voisinage de chacun de ses points. ℚ n’est voisinage d’aucun point : tout intervalle ouvert contient des irrationnels.</p></div>
<div class="warn"><p>Un voisinage n’est pas forcément petit ni symétrique : ]−100 ; 3[ est un voisinage de 2, et [0 ; 1] ∪ {5} aussi est un voisinage de 0,5. Seul compte ce qui se passe <b>tout près</b> de <i>a</i>.</p></div>`},
  {kind:'Pratique',h:'Le plus grand rayon',p:'On veut que le voisinage ouvert ]2 − <i>r</i> ; 2 + <i>r</i>[ soit contenu dans l’intervalle <i>I</i> = ]0 ; 3]. Trouve le <b>plus grand</b> rayon <i>r</i> qui convient.',
   params:[{id:'r',l:'r',min:0.1,max:2,step:0.1,v:1.5}],
   draw:v=>{ const P=axe([-1,4.5],{h:130}); inter(P,0,3,false,true,{c:'var(--muted)',w:9}); const ok=2-v.r>=0&&2+v.r<=3; inter(P,2-v.r,2+v.r,false,false,{c:ok?'var(--ok)':'var(--bad)',w:5,y:0.5}); P.dot(2,0.5,{c:'var(--ink)',r:5,l:'a = 2',dy:-10}); return P.svg(); },
   info:v=>`]${fmt(2-v.r)} ; ${fmt(2+v.r)}[ ${2-v.r>=0&&2+v.r<=3?'⊂ ]0 ; 3] : ça convient.':'déborde de ]0 ; 3].'}`,
   ok:v=>Math.abs(v.r-1)<1e-9,
   why:'Il faut 2 − r ≥ 0 et 2 + r ≤ 3, soit r ≤ 2 et r ≤ 1. Le plus grand rayon est r = 1 : ]1 ; 3[ ⊂ ]0 ; 3]. La borne la plus proche de 2 (ici 3, à distance 1) impose le rayon.'},
  {kind:'Théorie',h:'Point intérieur, intérieur d’un ensemble',
   p:`<p>Changeons de point de vue : au lieu de partir du point et de chercher ses voisinages, partons d’un ensemble et classons ses points.</p>
<div class="def"><p>Soit <i>A</i> ⊂ ℝ. Un réel <i>a</i> est un <b>point intérieur</b> de <i>A</i> si <i>A</i> est un voisinage de <i>a</i>, c’est-à-dire s’il existe <i>r</i> &gt; 0 avec ]<i>a</i> − <i>r</i> ; <i>a</i> + <i>r</i>[ ⊂ <i>A</i>. L’ensemble des points intérieurs est l’<b>intérieur</b> de <i>A</i>, noté Å. Un ensemble dont tous les points sont intérieurs est dit <b>ouvert</b>.</p></div>
<div class="idea"><p>Un point intérieur est entouré de <i>A</i> de toutes parts. Les points de <i>A</i> qui ne sont pas intérieurs sont « au bord ». L’intérieur de <i>A</i> est toujours contenu dans <i>A</i>, et il peut être beaucoup plus petit, voire vide.</p></div>
<div class="ex"><p>L’intérieur de [1 ; 4] est ]1 ; 4[ : 1 et 4 sont dans l’ensemble mais pas intérieurs. L’intérieur de ]1 ; 4[ est ]1 ; 4[ lui-même : un intervalle ouvert est un ensemble ouvert. L’intérieur de {3} est vide. L’intérieur de ℤ est vide. L’intérieur de ℚ est vide aussi : tout voisinage ouvert contient des irrationnels, donc n’est pas inclus dans ℚ.</p></div>
<div class="why"><p>Pourquoi ]1 ; 4[ est ouvert : pour <i>a</i> ∈ ]1 ; 4[, le rayon <i>r</i> = min(<i>a</i> − 1, 4 − <i>a</i>) est &gt; 0 et ]<i>a</i> − <i>r</i> ; <i>a</i> + <i>r</i>[ ⊂ ]1 ; 4[. Plus <i>a</i> s’approche du bord, plus le rayon doit être petit, mais il existe toujours.</p></div>`},
  {h:'Intérieur ou au bord ?',p:'Soit <i>A</i> = [1 ; 2] ∪ {3}. Lequel de ces réels est un point intérieur de <i>A</i>&nbsp;?',
   opts:['1','3','1,999','2'],ans:2,
   why:'Autour de 1,999, le voisinage ]1,998 ; 2[ est contenu dans A : il est intérieur. En 1 et en 2, tout voisinage déborde de [1 ; 2] (vers la gauche de 1, vers la droite de 2). En 3, tout voisinage contient des réels proches de 3 qui ne sont pas dans A.'},
  {kind:'Théorie',h:'Voisinages de l’infini',
   p:`<p>Plus tard, on écrira « <i>x</i> → +∞ » ou « <i>u</i><sub><i>n</i></sub> → +∞ ». Pour que ces phrases aient le même sens que les limites finies, on définit des voisinages de +∞ et de −∞, bien que ces symboles ne soient pas des réels.</p>
<div class="def"><p>Une partie <i>V</i> ⊂ ℝ est un <b>voisinage de +∞</b> s’il existe un réel <i>A</i> tel que ]<i>A</i> ; +∞[ ⊂ <i>V</i>. Elle est un <b>voisinage de −∞</b> s’il existe <i>B</i> tel que ]−∞ ; <i>B</i>[ ⊂ <i>V</i>.</p></div>
<div class="idea"><p>Être « près de +∞ », c’est être au-delà d’un certain seuil <i>A</i>, aussi grand qu’on veut. Le rôle du rayon <i>r</i> (petit) est joué par le seuil <i>A</i> (grand). Avec cette convention, « <i>x</i> appartient à un voisinage de +∞ » se traduit par <i>x</i> &gt; <i>A</i>, exactement comme « <i>x</i> appartient à un voisinage de <i>a</i> » se traduit par |<i>x</i> − <i>a</i>| &lt; <i>r</i>.</p></div>
<div class="ex"><p>]10 ; +∞[, [−3 ; +∞[ et ℝ \\ [0 ; 1] sont des voisinages de +∞ (le dernier contient ]1 ; +∞[). ℕ n’en est pas un : il ne contient aucun intervalle. ]−∞ ; 0[ est un voisinage de −∞ mais pas de +∞.</p></div>
<div class="blk" data-t="Remarque"><p>On note parfois ℝ̄ = ℝ ∪ {−∞, +∞} la <b>droite réelle achevée</b>, ordonnée par −∞ &lt; <i>x</i> &lt; +∞ pour tout réel <i>x</i>. Dans ℝ̄, toute partie non vide a une borne supérieure (éventuellement +∞) : c’est commode, mais +∞ n’a pas d’opposé ni d’inverse, et on ne calcule pas avec lui comme avec un réel.</p></div>`},
  {kind:'Méthode',h:'Passer d’un intervalle ouvert à une condition |x − a| < r',
   p:'<p><b>Quand :</b> on veut écrire un intervalle ouvert borné comme voisinage de son centre, ou inversement lire |<i>x</i> − <i>a</i>| &lt; <i>r</i> comme un intervalle. Cette traduction est constante dans les preuves de limite. <b>Pourquoi ça marche :</b> |<i>x</i> − <i>a</i>| &lt; <i>r</i> ⇔ <i>a</i> − <i>r</i> &lt; <i>x</i> &lt; <i>a</i> + <i>r</i> ; le centre est le milieu des bornes, le rayon la moitié de la longueur. <b>Comment :</b></p><ol><li>d’un intervalle ]<i>c</i> ; <i>d</i>[ vers |<i>x</i> − <i>a</i>| &lt; <i>r</i> : <i>a</i> = (<i>c</i> + <i>d</i>)/2 et <i>r</i> = (<i>d</i> − <i>c</i>)/2 ;</li><li>de |<i>x</i> − <i>a</i>| &lt; <i>r</i> vers l’intervalle : bornes <i>a</i> − <i>r</i> et <i>a</i> + <i>r</i>, crochets ouverts (fermés si ≤) ;</li><li>pour une condition |<i>x</i> − <i>a</i>| &lt; <i>r</i> avec <i>x</i> ≠ <i>a</i>, enlève le centre : ]<i>a</i> − <i>r</i> ; <i>a</i>[ ∪ ]<i>a</i> ; <i>a</i> + <i>r</i>[.</li></ol>',
   demo:{enonce:'Écris ]1,8 ; 2,4[ sous la forme {<i>x</i> : |<i>x</i> − <i>a</i>| &lt; <i>r</i>}, puis écris {<i>x</i> : |<i>x</i> + 3| ≤ 0,5} comme intervalle.',
    etapes:[{f:'Centre : <i>a</i> = (1,8 + 2,4)/2 = 2,1. Rayon : <i>r</i> = (2,4 − 1,8)/2 = 0,3.',w:'Le milieu et la demi-longueur.'},
     {f:']1,8 ; 2,4[ = {<i>x</i> ∈ ℝ : |<i>x</i> − 2,1| &lt; 0,3}.',w:'Vérification : 2,1 − 0,3 = 1,8 et 2,1 + 0,3 = 2,4.'},
     {f:'|<i>x</i> + 3| ≤ 0,5 s’écrit |<i>x</i> − (−3)| ≤ 0,5 : centre −3, rayon 0,5.',w:'Attention au signe : x + 3 = x − (−3).'},
     {f:'−0,5 ≤ <i>x</i> + 3 ≤ 0,5 ⇔ −3,5 ≤ <i>x</i> ≤ −2,5 : l’intervalle est [−3,5 ; −2,5].',w:'Inégalités larges, donc crochets fermés.'}],
    conclusion:']1,8 ; 2,4[ est le voisinage ouvert de centre 2,1 et de rayon 0,3 ; {|<i>x</i> + 3| ≤ 0,5} est le segment [−3,5 ; −2,5].'}},
  {h:'Centre et rayon',p:'On écrit l’intervalle ]−1 ; 6[ sous la forme {<i>x</i> : |<i>x</i> − <i>a</i>| &lt; <i>r</i>}. Que vaut le rayon <i>r</i>&nbsp;?',lab:'r =',ans:3.5,tol:0.001,
   why:'Le centre est (−1 + 6)/2 = 2,5 et le rayon la demi-longueur (6 − (−1))/2 = 3,5. Contrôle : 2,5 − 3,5 = −1 et 2,5 + 3,5 = 6.'},
  {kind:'Récapitulatif',h:'Ce qu’il faut retenir',
   p:`<p>Ce chapitre installe le vocabulaire géométrique de la droite réelle, utilisé dans toutes les définitions de limite.</p>
<div class="keep"><ul><li><b>Droite réelle</b> : bijection entre ℝ et une droite ; <i>a</i> &lt; <i>b</i> = « à gauche » ; distance |<i>b</i> − <i>a</i>|.</li><li><b>Intervalle</b> : contient tout ce qui est entre deux de ses points. Neuf types : crochet vers l’intérieur = borne incluse ; ±∞ toujours exclus.</li><li>∩ de deux intervalles : max des bornes gauches, min des bornes droites. ∪ : un intervalle seulement s’ils se chevauchent ou se touchent.</li><li><b>Segments emboîtés</b> [<i>a</i><sub><i>n</i></sub> ; <i>b</i><sub><i>n</i></sub>] : intersection non vide (sup des <i>a</i><sub><i>n</i></sub>). Faux pour ]0 ; 1/<i>n</i>[ ou [<i>n</i> ; +∞[.</li><li><b>Voisinage</b> de <i>a</i> : contient un ]<i>a</i> − <i>r</i> ; <i>a</i> + <i>r</i>[, <i>r</i> &gt; 0. En valeur absolue : |<i>x</i> − <i>a</i>| &lt; <i>r</i>.</li><li><b>Point intérieur</b> de <i>A</i> : <i>A</i> est un voisinage de ce point. Intérieur de [1 ; 4] = ]1 ; 4[ ; intérieur de ℚ = ∅.</li><li><b>Voisinage de +∞</b> : contient un ]<i>A</i> ; +∞[. Le seuil <i>A</i> remplace le rayon <i>r</i>.</li><li>Méthode : ]<i>c</i> ; <i>d</i>[ = {|<i>x</i> − <i>a</i>| &lt; <i>r</i>} avec <i>a</i> = (<i>c</i> + <i>d</i>)/2, <i>r</i> = (<i>d</i> − <i>c</i>)/2.</li></ul></div>`},
  {kind:'Problème',h:'Des ouverts emboîtés qui se referment',
   p:'Pour <i>n</i> ≥ 1, on pose <i>I</i><sub><i>n</i></sub> = ]−1/<i>n</i> ; 1 + 1/<i>n</i>[. Ces intervalles ouverts sont emboîtés : <i>I</i><sub>1</sub> = ]−1 ; 2[, <i>I</i><sub>2</sub> = ]−1/2 ; 3/2[, etc. On cherche leur intersection <i>I</i>, c’est-à-dire l’ensemble des réels qui appartiennent à <b>tous</b> les <i>I</i><sub><i>n</i></sub>. Le résultat surprend : une intersection d’ouverts peut ne pas être ouverte.',
   fig:(()=>{ const P=axe([-1.3,2.3],{h:170,step:1}); const cols=['var(--accent)','var(--spark)','var(--ok)','var(--math)']; [1,2,3,4].forEach((n,i)=>inter(P,-1/n,1+1/n,false,false,{y:0.75-i*0.4,c:cols[i],w:5})); inter(P,0,1,true,true,{y:-0.85,c:'var(--bad)',w:5}); P.text(1,-0.85,'I ?',{dx:10,dy:4,c:'var(--bad)'}); return P.svg(); })(),
   parts:[
    {q:'a) Quelle est la longueur de <i>I</i>₃ ? Donne une fraction ou arrondis au millième.',lab:'longueur =',ans:5/3,tol:0.001,hint:'Longueur = borne droite − borne gauche.',why:'(1 + 1/3) − (−1/3) = 1 + 2/3 = 5/3 ≈ 1,667.'},
    {q:'b) Le réel 0 appartient-il à tous les <i>I</i><sub><i>n</i></sub>&nbsp;?',opts:['Non : 0 est la limite des bornes gauches, donc il finit par sortir','Oui : −1/<i>n</i> &lt; 0 &lt; 1 + 1/<i>n</i> pour tout <i>n</i> ≥ 1','Oui, mais seulement pour <i>n</i> ≤ 10','Non, car les intervalles sont ouverts'],ans:1,hint:'Écris la double inégalité qui définit l’appartenance à Iₙ.',why:'−1/n est strictement négatif et 1 + 1/n strictement supérieur à 1 : 0 (et de même 1) vérifie la double inégalité pour tout n. Le fait que 0 soit la limite des bornes n’empêche rien : il n’est jamais égal à une borne.'},
    {q:'c) Quel est le plus petit <i>n</i> tel que −0,001 ∉ <i>I</i><sub><i>n</i></sub>&nbsp;?',lab:'n =',ans:1000,hint:'−0,001 sort dès que −1/n ≥ −0,001 ; attention, l’intervalle est ouvert.',why:'−0,001 ∈ Iₙ ⇔ −1/n &lt; −0,001 ⇔ 1/n &gt; 0,001 ⇔ n &lt; 1000. Pour n = 1000, la borne gauche vaut exactement −0,001, exclue : −0,001 ∉ I₁₀₀₀. De même tout x &lt; 0 sort d’un Iₙ (Archimède).'},
    {q:'d) Que vaut l’intersection <i>I</i> de tous les <i>I</i><sub><i>n</i></sub>&nbsp;?',opts:[']0 ; 1[','[0 ; 1]','{0, 1}','∅'],ans:1,hint:'Traite trois cas : x &lt; 0, 0 ≤ x ≤ 1, x &gt; 1.',why:'Si 0 ≤ x ≤ 1, x ∈ Iₙ pour tout n (question b). Si x &lt; 0, un n avec 1/n ≤ −x le fait sortir ; si x &gt; 1, un n avec 1/n ≤ x − 1 aussi. Donc I = [0 ; 1], un segment fermé : ses bornes ne sont pas des points intérieurs, alors que chaque Iₙ était ouvert.'},
   ],
   sol:'Soit <i>x</i> réel. Si 0 ≤ <i>x</i> ≤ 1, alors −1/<i>n</i> &lt; 0 ≤ <i>x</i> ≤ 1 &lt; 1 + 1/<i>n</i> pour tout <i>n</i> : <i>x</i> ∈ <i>I</i>. Si <i>x</i> &lt; 0, la propriété d’Archimède fournit <i>n</i> avec 1/<i>n</i> ≤ −<i>x</i>, c’est-à-dire <i>x</i> ≤ −1/<i>n</i>, et <i>x</i> ∉ <i>I</i><sub><i>n</i></sub> ; pour <i>x</i> = −0,001, le premier tel <i>n</i> est 1000. Si <i>x</i> &gt; 1, de même avec 1/<i>n</i> ≤ <i>x</i> − 1. Conclusion : <b><i>I</i> = [0 ; 1]</b>. Chaque <i>I</i><sub><i>n</i></sub> est ouvert (tous ses points sont intérieurs), mais l’intersection infinie ne l’est plus : 0 et 1 sont au bord. Une intersection <b>finie</b> d’ouverts reste ouverte (prendre le plus petit rayon) ; c’est l’infinité qui change tout.'},
  {kind:'Problème',h:'Autour d’un point d’accumulation',
   p:'Soit <i>A</i> = {1/<i>n</i> : <i>n</i> ∈ ℕ*} ∪ {0} = {0, 1, 1/2, 1/3, …}. On étudie la façon dont les points de <i>A</i> sont entourés : lesquels sont isolés (un petit voisinage ne contient aucun autre point de <i>A</i>), lesquels sont des « points d’accumulation » (tout voisinage contient d’autres points de <i>A</i>). Cette distinction prépare la notion de limite d’une suite.',
   fig:(()=>{ const P=axe([-0.2,1.2],{h:110,step:0.5}); for(let n=1;n<=30;n++) P.dot(1/n,0,{r:3.5,c:'var(--accent)'}); P.dot(0,0,{r:5,c:'var(--bad)',l:'0',dy:-10}); P.dot(0.2,0,{r:5,c:'var(--spark)',l:'1/5',dy:-10}); return P.svg(); })(),
   parts:[
    {q:'a) Quelle est la distance entre 1/5 et le point de <i>A</i> le plus proche ? Donne une fraction ou arrondis au millième.',lab:'distance =',ans:1/30,tol:0.0005,hint:'Les voisins de 1/5 dans A sont 1/4 et 1/6. Lequel est le plus proche ?',why:'1/5 − 1/6 = 1/30 ≈ 0,0333 et 1/4 − 1/5 = 1/20 = 0,05. Le plus proche est 1/6, à distance 1/30.'},
    {q:'b) Pour quels rayons <i>r</i> le voisinage ]1/5 − <i>r</i> ; 1/5 + <i>r</i>[ ne contient-il aucun autre point de <i>A</i> que 1/5&nbsp;?',opts:['Pour <i>r</i> ≤ 1/30','Pour aucun : tout voisinage de 1/5 contient d’autres points de <i>A</i>','Pour <i>r</i> ≤ 1/20','Pour <i>r</i> &lt; 1/5'],ans:0,hint:'Le voisinage ouvert exclut ses bornes : le point 1/6 est-il dedans quand r = 1/30 ?',why:'Pour r ≤ 1/30, les voisins 1/6 et 1/4 sont à distance ≥ r, donc hors du voisinage ouvert, et les autres points de A sont plus loin encore. Avec r = 1/20, 1/6 est dedans. Le point 1/5 est isolé dans A.'},
    {q:'c) Un voisinage ]−<i>r</i> ; <i>r</i>[ de 0, avec <i>r</i> = 0,003, contient combien de points de <i>A</i> autres que 0&nbsp;?',opts:['Aucun','Un nombre fini mais non nul','Une infinité','Exactement 333'],ans:2,hint:'1/n &lt; 0,003 ⇔ n &gt; 333,3 : combien d’entiers vérifient cela ?',why:'Tous les 1/n avec n ≥ 334 vérifient 0 &lt; 1/n &lt; 0,003 : il y en a une infinité. Pour tout r &gt; 0 c’est pareil (Archimède) : 0 est un point d’accumulation de A.'},
    {q:'d) 0 est-il un point intérieur de <i>A</i>&nbsp;?',opts:['Oui, puisque tout voisinage de 0 contient une infinité de points de <i>A</i>','Non : tout voisinage de 0 contient des réels négatifs, qui ne sont pas dans <i>A</i>','Oui, car 0 ∈ <i>A</i>','Non, car 0 n’appartient pas à <i>A</i>'],ans:1,hint:'Point intérieur = A contient tout un voisinage ouvert de 0. Regarde à gauche de 0.',why:'Pour être intérieur, il faudrait ]−r ; r[ ⊂ A pour un r &gt; 0 ; or −r/2 ∉ A. Contenir une infinité de points de A n’est pas la même chose que contenir tout un voisinage. L’intérieur de A est vide.'},
   ],
   sol:'Les voisins de 1/5 dans <i>A</i> sont 1/4 (à 1/20) et 1/6 (à 1/30) ; le voisinage ouvert de rayon <i>r</i> ≤ 1/30 ne contient donc aucun autre point de <i>A</i> : 1/5 est <b>isolé</b>, et il en va de même de chaque 1/<i>n</i>. Autour de 0, c’est l’inverse : pour tout <i>r</i> &gt; 0, Archimède donne une infinité d’entiers <i>n</i> &gt; 1/<i>r</i>, et tous les 1/<i>n</i> correspondants sont dans ]−<i>r</i> ; <i>r</i>[ (pour <i>r</i> = 0,003, tous les <i>n</i> ≥ 334). 0 est un <b>point d’accumulation</b> de <i>A</i>. Pourtant 0 n’est pas intérieur à <i>A</i> : ]−<i>r</i> ; <i>r</i>[ contient des négatifs, absents de <i>A</i>. L’intérieur de <i>A</i> est vide. Au chapitre suivant, « 1/<i>n</i> tend vers 0 » dira exactement : tout voisinage de 0 contient tous les 1/<i>n</i> à partir d’un certain rang.'},
]},
/* ===================== 4. SUITES NUMÉRIQUES ET CONVERGENCE ===================== */
{subj:'gred',sem:'ana',id:'gred-suites-num',h:'Suites numériques et convergence',p:'Qu’est-ce qu’une suite, et que veut dire exactement « tendre vers une limite » : la définition ε–N expliquée pas à pas, puis les trois premiers théorèmes (unicité, suite convergente bornée, suites monotones bornées).',steps:[
  {kind:'Théorie',h:'Qu’est-ce qu’une suite ?',
   p:`<p>Une suite est une liste infinie de nombres, numérotés : un premier terme, un deuxième, et ainsi de suite sans fin. En mathématiques, « numéroter » se dit avec une application.</p>
<div class="def"><p>Une <b>suite numérique</b> est une application <i>u</i> : ℕ → ℝ. L’image de <i>n</i> se note <i>u</i><sub><i>n</i></sub> (plutôt que <i>u</i>(<i>n</i>)) et s’appelle le <b>terme de rang <i>n</i></b> (ou d’indice <i>n</i>). La suite elle-même se note (<i>u</i><sub><i>n</i></sub>) ou (<i>u</i><sub><i>n</i></sub>)<sub><i>n</i> ∈ ℕ</sub>. Elle peut aussi commencer au rang 1, ou à tout rang <i>n</i><sub>0</sub>.</p></div>
<div class="idea"><p>Deux façons de définir une suite. <b>Explicite</b> : une formule donne <i>u</i><sub><i>n</i></sub> directement en fonction de <i>n</i>, comme <i>u</i><sub><i>n</i></sub> = 1/(<i>n</i> + 1). <b>Par récurrence</b> : on donne le premier terme et une règle pour passer d’un terme au suivant, comme <i>v</i><sub>0</sub> = 1 et <i>v</i><sub><i>n</i>+1</sub> = 2<i>v</i><sub><i>n</i></sub> + 1. Pour connaître <i>v</i><sub>100</sub>, il faut alors calculer tous les termes précédents (ou deviner une formule et la prouver par récurrence).</p></div>
<div class="ex"><p><i>u</i><sub><i>n</i></sub> = 1/(<i>n</i> + 1) : 1, 1/2, 1/3, 1/4, … ; <i>v</i><sub>0</sub> = 1, <i>v</i><sub><i>n</i>+1</sub> = 2<i>v</i><sub><i>n</i></sub> + 1 : 1, 3, 7, 15, 31, … (on reconnaît <i>v</i><sub><i>n</i></sub> = 2<sup><i>n</i>+1</sup> − 1) ; <i>w</i><sub><i>n</i></sub> = (−1)<sup><i>n</i></sup> : 1, −1, 1, −1, …</p></div>
<div class="warn"><p>Ne confonds pas la suite (<i>u</i><sub><i>n</i></sub>), qui est une application, avec l’ensemble de ses valeurs {<i>u</i><sub><i>n</i></sub> : <i>n</i> ∈ ℕ}. La suite (−1)<sup><i>n</i></sup> a une infinité de termes mais son ensemble de valeurs est {−1, 1}. L’ordre des termes compte pour la suite, pas pour l’ensemble.</p></div>`,
   fig:(()=>{ const P=suite(n=>1/(n+1),{n0:0,N:15,y:[-0.2,1.2],h:170,lx:5,ly:0.5}); P.text(0,1,'u₀',{dx:8,dy:-4}).text(1,0.5,'u₁',{dx:8,dy:-2}); return P.svg(); })()},
  {kind:'Théorie',h:'Monotone, bornée : le vocabulaire des suites',
   p:`<p>Avant de parler de limite, on décrit l’allure globale d’une suite : monte-t-elle, descend-elle, reste-t-elle dans une bande ? Choisis une suite sur la figure et lis son portrait.</p>
<div class="def"><p>La suite (<i>u</i><sub><i>n</i></sub>) est <b>croissante</b> si <i>u</i><sub><i>n</i>+1</sub> ≥ <i>u</i><sub><i>n</i></sub> pour tout <i>n</i>, <b>décroissante</b> si <i>u</i><sub><i>n</i>+1</sub> ≤ <i>u</i><sub><i>n</i></sub> pour tout <i>n</i>, <b>monotone</b> si elle est l’un ou l’autre (strictement si les inégalités sont strictes). Elle est <b>majorée</b> s’il existe <i>M</i> avec <i>u</i><sub><i>n</i></sub> ≤ <i>M</i> pour tout <i>n</i>, <b>minorée</b> s’il existe <i>m</i> avec <i>u</i><sub><i>n</i></sub> ≥ <i>m</i> pour tout <i>n</i>, <b>bornée</b> si elle est les deux, ce qui équivaut à : il existe <i>K</i> avec |<i>u</i><sub><i>n</i></sub>| ≤ <i>K</i> pour tout <i>n</i>.</p></div>
<div class="idea"><p>Ces mots s’appliquent à l’ensemble des valeurs {<i>u</i><sub><i>n</i></sub>} : la suite est majorée si cet ensemble l’est, au sens du chapitre sur la borne supérieure. Par contre « croissante » parle de l’ordre des termes, et n’a pas de sens pour un ensemble.</p></div>
<div class="ex"><p>1/<i>n</i> : décroissante, bornée (0 &lt; 1/<i>n</i> ≤ 1). √<i>n</i> : croissante, minorée par 0, non majorée. (−1)<sup><i>n</i></sup> : bornée, non monotone. (−1)<sup><i>n</i></sup> <i>n</i> : ni monotone, ni majorée, ni minorée.</p></div>
<div class="warn"><p>Une suite peut n’être ni croissante ni décroissante tout en ayant une limite : (−1)<sup><i>n</i></sup>/<i>n</i> oscille autour de 0 en s’en rapprochant. Monotone n’est pas une condition nécessaire pour converger.</p></div>`,
   params:[{id:'k',l:'Suite',min:0,max:3,v:0}],
   draw:v=>{ const u=[n=>1/n,n=>Math.sqrt(n),n=>(-1)**n,n=>(-1)**n/n][v.k]; return suite(u,{n0:1,N:20,y:[[-0.2,1.2],[-0.5,5],[-1.5,1.5],[-1.2,1.2]][v.k],h:200,lx:5,ly:[0.5,1,1,0.5][v.k]}).svg(); },
   info:v=>['<i>u</i><sub><i>n</i></sub> = 1/<i>n</i> : décroissante, bornée (entre 0 et 1).','<i>u</i><sub><i>n</i></sub> = √<i>n</i> : croissante, minorée par 0, non majorée.','<i>u</i><sub><i>n</i></sub> = (−1)<sup><i>n</i></sup> : bornée, pas monotone.','<i>u</i><sub><i>n</i></sub> = (−1)<sup><i>n</i></sup>/<i>n</i> : bornée, pas monotone, et pourtant elle se rapproche de 0.'][v.k]},
  {kind:'Méthode',h:'Étudier la monotonie d’une suite',
   p:'<p><b>Quand :</b> on demande si (<i>u</i><sub><i>n</i></sub>) est croissante ou décroissante. <b>Pourquoi ça marche :</b> croissante signifie <i>u</i><sub><i>n</i>+1</sub> − <i>u</i><sub><i>n</i></sub> ≥ 0 pour tout <i>n</i> : tout se ramène au signe d’une différence. Si tous les termes sont strictement positifs, on peut aussi comparer le quotient <i>u</i><sub><i>n</i>+1</sub>/<i>u</i><sub><i>n</i></sub> à 1 (règles de l’ordre : diviser par un positif conserve le sens). <b>Comment :</b></p><ol><li>écris <i>u</i><sub><i>n</i>+1</sub> en remplaçant <i>n</i> par <i>n</i> + 1 partout ;</li><li>calcule <i>u</i><sub><i>n</i>+1</sub> − <i>u</i><sub><i>n</i></sub>, réduis au même dénominateur, simplifie ;</li><li>détermine le signe pour tout <i>n</i> ≥ <i>n</i><sub>0</sub>, et conclus.</li></ol>',
   demo:{enonce:`Étudie la monotonie de <i>u</i><sub><i>n</i></sub> = ${F('2<i>n</i> − 1','<i>n</i> + 2')} pour <i>n</i> ≥ 0.`,
    etapes:[{f:`<i>u</i><sub><i>n</i>+1</sub> = ${F('2(<i>n</i> + 1) − 1','(<i>n</i> + 1) + 2')} = ${F('2<i>n</i> + 1','<i>n</i> + 3')}.`,w:'On remplace n par n + 1, sans oublier les parenthèses.'},
     {f:`<i>u</i><sub><i>n</i>+1</sub> − <i>u</i><sub><i>n</i></sub> = ${F('(2<i>n</i> + 1)(<i>n</i> + 2) − (2<i>n</i> − 1)(<i>n</i> + 3)','(<i>n</i> + 2)(<i>n</i> + 3)')}.`,w:'Même dénominateur pour soustraire.'},
     {f:`Numérateur : (2<i>n</i>² + 5<i>n</i> + 2) − (2<i>n</i>² + 5<i>n</i> − 3) = 5. Donc <i>u</i><sub><i>n</i>+1</sub> − <i>u</i><sub><i>n</i></sub> = ${F('5','(<i>n</i> + 2)(<i>n</i> + 3)')}.`,w:'Les termes en n² et en n se simplifient.'},
     {f:'Pour <i>n</i> ≥ 0, le dénominateur est positif : la différence est strictement positive.',w:'Produit de deux nombres positifs.'}],
    conclusion:'(<i>u</i><sub><i>n</i></sub>) est <b>strictement croissante</b>. Elle est aussi majorée par 2, car 2 − <i>u</i><sub><i>n</i></sub> = 5/(<i>n</i> + 2) &gt; 0 : on y reviendra avec le théorème des suites monotones.'},
   note:'Pour une suite définie par récurrence, on étudie souvent le signe de <i>u</i><sub><i>n</i>+1</sub> − <i>u</i><sub><i>n</i></sub> par récurrence sur <i>n</i>.'},
  {h:'Sens de variation',p:`La suite <i>u</i><sub><i>n</i></sub> = ${F('<i>n</i> + 5','<i>n</i> + 1')} (<i>n</i> ≥ 0) est…`,
   opts:['croissante, car le numérateur augmente','décroissante : <i>u</i><sub><i>n</i>+1</sub> − <i>u</i><sub><i>n</i></sub> = −4/((<i>n</i> + 1)(<i>n</i> + 2))','non monotone : la différence change de signe','constante égale à 1'],ans:1,
   why:'uₙ₊₁ − uₙ = (n + 6)/(n + 2) − (n + 5)/(n + 1) = [(n + 6)(n + 1) − (n + 5)(n + 2)]/((n + 1)(n + 2)) = (n² + 7n + 6 − n² − 7n − 10)/(…) = −4/((n + 1)(n + 2)) &lt; 0. La suite décroît (de 5 vers 1).'},
  {kind:'Théorie',h:'L’idée de limite',
   p:`<p>Regarde <i>u</i><sub><i>n</i></sub> = 1 + (−1)<sup><i>n</i></sup>/<i>n</i> : 0, 3/2, 2/3, 5/4, 4/5, … Les termes sautent au-dessus et en dessous de 1, mais les sauts rétrécissent. On a envie de dire que la suite « tend vers 1 ». Que veut-on dire exactement ?</p>
<div class="idea"><p>Première tentative : « les termes se rapprochent de 1 ». Insuffisant : la suite 2 + 1/<i>n</i> se rapproche aussi de 1 (les distances diminuent) sans jamais s’en approcher à moins de 1. Deuxième tentative : « les termes deviennent aussi proches de 1 qu’on veut ». Mieux, mais 1/<i>n</i> si <i>n</i> est pair et 1 si <i>n</i> est impair s’approche de 0 autant qu’on veut, par moments, sans y « rester ». Il faut donc : <b>aussi proches qu’on veut, et à partir d’un moment, pour toujours</b>.</p></div>
<div class="def"><p>Formulation géométrique : (<i>u</i><sub><i>n</i></sub>) <b>tend vers <i>L</i></b> si, pour toute bande ]<i>L</i> − ε ; <i>L</i> + ε[ autour de <i>L</i>, aussi étroite soit-elle, <b>tous les termes à partir d’un certain rang</b> sont dans la bande. Autrement dit : tout voisinage de <i>L</i> contient tous les termes de la suite sauf un nombre fini d’entre eux.</p></div>
<div class="ex"><p>Pour <i>u</i><sub><i>n</i></sub> = 1 + (−1)<sup><i>n</i></sup>/<i>n</i> et la bande de demi-largeur ε = 0,1 autour de 1 : |<i>u</i><sub><i>n</i></sub> − 1| = 1/<i>n</i> &lt; 0,1 dès que <i>n</i> ≥ 11. Les dix premiers termes sortent de la bande, tous les autres y restent. Pour ε = 0,01, il faut attendre le rang 101. Quelle que soit la bande, on finit par y entrer définitivement.</p></div>`,
   fig:(()=>suite(n=>1+(-1)**n/n,{n0:1,N:25,y:[-0.2,1.7],h:200,lx:5,ly:0.5,L:1,e:0.1,N0:11}).svg())()},
  {kind:'Théorie',h:'La définition ε–N de la convergence',
   p:`<p>Traduisons la bande et le rang en symboles. Règle ε (la demi-largeur de la bande) puis <i>N</i> (le rang à partir duquel on regarde) : les termes rouges sont ceux qui, après <i>N</i>, sortent encore de la bande.</p>
<div class="def"><p>La suite (<i>u</i><sub><i>n</i></sub>) <b>converge</b> vers le réel <i>L</i>, ce qu’on note <i>u</i><sub><i>n</i></sub> → <i>L</i> ou lim <i>u</i><sub><i>n</i></sub> = <i>L</i>, si :</p><p style="text-align:center"><b>∀ε &gt; 0, ∃<i>N</i> ∈ ℕ, ∀<i>n</i> ≥ <i>N</i>, |<i>u</i><sub><i>n</i></sub> − <i>L</i>| &lt; ε.</b></p><p>Une suite qui ne converge vers aucun réel est dite <b>divergente</b>.</p></div>
<div class="idea"><p>Lis la phrase comme un jeu à deux. L’adversaire choisit ε &gt; 0, aussi petit qu’il veut : c’est la précision exigée. Tu réponds par un rang <i>N</i>, qui a le droit de dépendre de ε. Tu gagnes si, à partir de ce rang, tous les termes sont à moins de ε de <i>L</i> (|<i>u</i><sub><i>n</i></sub> − <i>L</i>| &lt; ε, c’est-à-dire <i>u</i><sub><i>n</i></sub> ∈ ]<i>L</i> − ε ; <i>L</i> + ε[). La suite converge si tu peux gagner <b>contre tout ε</b>.</p></div>
<div class="ex"><p>Pour <i>u</i><sub><i>n</i></sub> = 1 + (−1)<sup><i>n</i></sup>/<i>n</i> et <i>L</i> = 1 : |<i>u</i><sub><i>n</i></sub> − 1| = 1/<i>n</i>. Contre ε, réponds <i>N</i> = n’importe quel entier &gt; 1/ε (Archimède garantit qu’il en existe). Alors <i>n</i> ≥ <i>N</i> ⇒ 1/<i>n</i> ≤ 1/<i>N</i> &lt; ε. Tu gagnes toujours : <i>u</i><sub><i>n</i></sub> → 1.</p></div>
<div class="warn"><p>L’ordre des quantificateurs est essentiel : <i>N</i> vient <b>après</b> ε et en dépend. La phrase « ∃<i>N</i>, ∀ε &gt; 0, … » dirait qu’un même rang marche pour toutes les précisions, c’est-à-dire que la suite est constante égale à <i>L</i> à partir de <i>N</i>. Beaucoup plus fort, et presque jamais vrai.</p></div>`,
   params:[{id:'e',l:'ε',min:0.05,max:0.5,step:0.05,v:0.2},{id:'N',l:'N',min:1,max:30,v:3}],
   draw:v=>suite(n=>1+(-1)**n/n,{n0:1,N:30,y:[-0.2,1.7],h:210,lx:5,ly:0.5,L:1,e:v.e,N0:v.N}).svg(),
   info:v=>{ const need=Math.floor(1/v.e)+1, ok=v.N>=need; return `|<i>u</i><sub><i>n</i></sub> − 1| = 1/<i>n</i>. Avec ε = ${fmt(v.e)}, il faut 1/<i>n</i> &lt; ε, soit <i>n</i> ≥ ${need}. ${ok?'<b style="color:var(--ok)">Ton N convient</b> : tous les termes à partir du rang N sont dans la bande.':'<b style="color:var(--bad)">Ton N est trop petit</b> : des termes après N sortent encore de la bande.'}`; }},
  {kind:'Théorie',h:'Lire et nier la définition',
   p:`<p>Une définition avec trois quantificateurs se manipule avec les règles de la logique vues au tout début. Voici ce qu’il faut savoir en faire.</p>
<div class="blk" data-t="Rappel"><p>Nier une phrase quantifiée : on échange ∀ et ∃ dans l’ordre, sans toucher aux domaines, puis on nie la propriété finale.</p></div>
<div class="prop"><p>« (<i>u</i><sub><i>n</i></sub>) ne converge pas vers <i>L</i> » s’écrit : <b>∃ε &gt; 0, ∀<i>N</i> ∈ ℕ, ∃<i>n</i> ≥ <i>N</i>, |<i>u</i><sub><i>n</i></sub> − <i>L</i>| ≥ ε</b>. En mots : il existe une bande autour de <i>L</i> dont la suite ressort sans cesse, aussi loin qu’on aille.</p></div>
<div class="ex"><p><i>u</i><sub><i>n</i></sub> = (−1)<sup><i>n</i></sup> ne tend pas vers 1 : prends ε = 1 ; pour tout <i>N</i>, le rang impair <i>n</i> = 2<i>N</i> + 1 ≥ <i>N</i> donne |<i>u</i><sub><i>n</i></sub> − 1| = 2 ≥ 1. Le même argument (avec les rangs pairs) montre qu’elle ne tend pas vers −1, et pour tout autre <i>L</i>, l’un des deux nombres |1 − <i>L</i>|, |−1 − <i>L</i>| vaut au moins 1 : la suite diverge.</p></div>
<div class="idea"><p>Trois remarques qui simplifient la vie. (1) Remplacer « &lt; ε » par « ≤ ε », ou « <i>n</i> ≥ <i>N</i> » par « <i>n</i> &gt; <i>N</i> », donne une définition équivalente (change ε en ε/2, ou <i>N</i> en <i>N</i> + 1). (2) Il suffit de traiter les petits ε : si un <i>N</i> marche pour ε, il marche pour tout ε′ &gt; ε. (3) Modifier un nombre fini de termes ne change ni la convergence ni la limite : il suffit d’augmenter <i>N</i>.</p></div>`},
  {kind:'Méthode',h:'Prouver une convergence avec la définition',
   p:'<p><b>Quand :</b> on connaît (ou on devine) la limite <i>L</i> et on doit prouver <i>u</i><sub><i>n</i></sub> → <i>L</i> en revenant à la définition. <b>Pourquoi ça marche :</b> la définition demande, pour chaque ε, un rang ; on l’obtient en résolvant l’inéquation |<i>u</i><sub><i>n</i></sub> − <i>L</i>| &lt; ε en <i>n</i>. <b>Comment :</b></p><ol><li>calcule et simplifie |<i>u</i><sub><i>n</i></sub> − <i>L</i>| (même dénominateur, valeur absolue) ;</li><li>écris « Soit ε &gt; 0 » et résous |<i>u</i><sub><i>n</i></sub> − <i>L</i>| &lt; ε : tu obtiens une condition du type <i>n</i> &gt; <i>g</i>(ε) ;</li><li>choisis <i>N</i> = un entier &gt; <i>g</i>(ε) (il existe par Archimède) et vérifie que <i>n</i> ≥ <i>N</i> entraîne bien l’inégalité (souvent parce que |<i>u</i><sub><i>n</i></sub> − <i>L</i>| décroît) ;</li><li>conclus en citant la définition.</li></ol>',
   demo:{enonce:`Montre que <i>u</i><sub><i>n</i></sub> = ${F('3<i>n</i> + 1','<i>n</i> + 2')} converge vers 3, et donne un rang explicite pour ε = 0,1.`,
    etapes:[{f:`<i>u</i><sub><i>n</i></sub> − 3 = ${F('3<i>n</i> + 1 − 3(<i>n</i> + 2)','<i>n</i> + 2')} = ${F('−5','<i>n</i> + 2')}, donc |<i>u</i><sub><i>n</i></sub> − 3| = ${F('5','<i>n</i> + 2')}.`,w:'On mesure l’écart à la limite et on le simplifie.'},
     {f:'Soit ε &gt; 0. 5/(<i>n</i> + 2) &lt; ε ⇔ <i>n</i> + 2 &gt; 5/ε ⇔ <i>n</i> &gt; 5/ε − 2.',w:'Les deux membres sont positifs : on peut inverser en renversant le sens.'},
     {f:'Soit <i>N</i> un entier &gt; 5/ε − 2 (Archimède). Pour <i>n</i> ≥ <i>N</i> : <i>n</i> + 2 ≥ <i>N</i> + 2 &gt; 5/ε, donc 5/(<i>n</i> + 2) &lt; ε.',w:'L’écart décroît avec n : si le rang N convient, tous les suivants aussi.'},
     {f:'Pour ε = 0,1 : <i>n</i> &gt; 50 − 2 = 48, donc <i>N</i> = 49 convient ; <i>u</i><sub>49</sub> = 148/51 ≈ 2,902 et 3 − 2,902 &lt; 0,1.',w:'Un rang explicite, pour voir la définition fonctionner.'}],
    conclusion:'Pour tout ε &gt; 0 on a trouvé un rang <i>N</i> : par définition, <b><i>u</i><sub><i>n</i></sub> → 3</b>. Le rang <i>N</i> n’a pas besoin d’être le plus petit possible : n’importe quel entier assez grand fait l’affaire.'},
   note:'Si l’écart |<i>u</i><sub><i>n</i></sub> − <i>L</i>| ne se simplifie pas, on le <b>majore</b> par une expression plus simple <i>v</i><sub><i>n</i></sub> qui tend vers 0 : |<i>u</i><sub><i>n</i></sub> − <i>L</i>| ≤ <i>v</i><sub><i>n</i></sub> &lt; ε suffit.'},
  {kind:'Pratique',h:'Le premier rang qui convient',p:'Pour <i>u</i><sub><i>n</i></sub> = (3<i>n</i> + 1)/(<i>n</i> + 2) et ε = 0,05, trouve le <b>plus petit</b> entier <i>N</i> tel que |<i>u</i><sub><i>n</i></sub> − 3| &lt; 0,05 pour tout <i>n</i> ≥ <i>N</i>.',
   params:[{id:'N',l:'N',min:90,max:110,v:95}],
   draw:v=>{ const P=plane({x:[88,112],y:[2.92,2.98],h:200,grid:false,lx:5,ly:0.02}); P.rect(88,2.95,24,0.03,{fill:'var(--ok)',fo:.15,c:null}).seg(88,2.95,112,2.95,{c:'var(--ok)',w:1.5,dash:true}).seg(v.N,2.92,v.N,2.98,{c:'var(--muted)',w:1.5});
     for(let n=89;n<=111;n++){ const u=(3*n+1)/(n+2); P.dot(n,u,{r:4,c:n<v.N?'var(--muted)':u>2.95+1e-12?'var(--accent)':'var(--bad)'}); } P.text(v.N,2.98,'N',{dx:4,dy:14}).text(112,2.95,'3 − ε',{a:'end',dy:-5,c:'var(--ok)'}); return P.svg(); },
   info:v=>`|<i>u</i><sub><i>N</i></sub> − 3| = 5/${v.N+2} ≈ ${fmt(5/(v.N+2),4)} ${5/(v.N+2)<0.05?'&lt; 0,05.':'≥ 0,05.'}`,
   ok:v=>v.N===99,why:'5/(n + 2) &lt; 0,05 ⇔ n + 2 &gt; 100 ⇔ n &gt; 98. Le premier entier est N = 99 ; pour n = 98 l’écart vaut exactement 0,05, pas strictement moins.'},
  {h:'Un rang pour une précision',p:'Pour <i>u</i><sub><i>n</i></sub> = 1 − 2/<i>n</i> (<i>n</i> ≥ 1) et <i>L</i> = 1, quel est le plus petit <i>N</i> tel que |<i>u</i><sub><i>n</i></sub> − 1| &lt; 0,001 pour tout <i>n</i> ≥ <i>N</i>&nbsp;?',lab:'N =',ans:2001,
   why:'|uₙ − 1| = 2/n &lt; 0,001 ⇔ n &gt; 2000. Pour n = 2000 l’écart vaut exactement 0,001 : le premier rang qui convient est N = 2001, et comme 2/n décroît, tous les suivants conviennent.'},
  {kind:'Théorie',h:'Unicité de la limite',
   p:`<p>On a écrit « la » limite. Encore faut-il qu’une suite ne puisse pas tendre vers deux nombres différents. C’est le premier théorème sur les limites, et sa preuve est le modèle de beaucoup d’autres.</p>
<div class="thm"><p>Si (<i>u</i><sub><i>n</i></sub>) converge vers <i>L</i> et vers <i>L</i>′, alors <i>L</i> = <i>L</i>′.</p></div>
<div class="why"><p>Par l’absurde, supposons <i>L</i> ≠ <i>L</i>′ et posons ε = |<i>L</i> − <i>L</i>′|/2 &gt; 0. Les bandes ]<i>L</i> − ε ; <i>L</i> + ε[ et ]<i>L</i>′ − ε ; <i>L</i>′ + ε[ sont disjointes. La convergence vers <i>L</i> donne un rang <i>N</i> à partir duquel |<i>u</i><sub><i>n</i></sub> − <i>L</i>| &lt; ε ; celle vers <i>L</i>′ un rang <i>N</i>′ pour |<i>u</i><sub><i>n</i></sub> − <i>L</i>′| &lt; ε. Pour <i>n</i> = max(<i>N</i>, <i>N</i>′), les deux inégalités sont vraies, et l’inégalité triangulaire donne |<i>L</i> − <i>L</i>′| ≤ |<i>L</i> − <i>u</i><sub><i>n</i></sub>| + |<i>u</i><sub><i>n</i></sub> − <i>L</i>′| &lt; 2ε = |<i>L</i> − <i>L</i>′|. Un nombre strictement plus petit que lui-même : contradiction.</p></div>
<div class="idea"><p>Un terme ne peut pas être à la fois tout près de <i>L</i> et tout près de <i>L</i>′ si ces deux nombres sont à distance fixe. L’astuce « ε = la moitié de la distance » et le « max des deux rangs » reviennent constamment.</p></div>
<div class="ex"><p>(−1)<sup><i>n</i></sup> semble « tendre vers 1 et vers −1 ». Le théorème dit que c’est impossible : elle ne tend donc vers aucun des deux (et en fait vers rien du tout, comme on l’a vu).</p></div>`},
  {kind:'Théorie',h:'Une suite convergente est bornée',
   p:`<p>La convergence impose une contrainte globale sur la suite : elle ne peut pas s’échapper vers l’infini.</p>
<div class="thm"><p>Toute suite convergente est bornée.</p></div>
<div class="why"><p>Soit <i>u</i><sub><i>n</i></sub> → <i>L</i>. Appliquons la définition avec ε = 1 : il existe <i>N</i> tel que, pour <i>n</i> ≥ <i>N</i>, |<i>u</i><sub><i>n</i></sub> − <i>L</i>| &lt; 1, donc |<i>u</i><sub><i>n</i></sub>| ≤ |<i>u</i><sub><i>n</i></sub> − <i>L</i>| + |<i>L</i>| &lt; 1 + |<i>L</i>| (inégalité triangulaire). Les termes avant le rang <i>N</i> sont en nombre <b>fini</b> : <i>u</i><sub>0</sub>, …, <i>u</i><sub><i>N</i>−1</sub>, et un ensemble fini a un maximum. Posons <i>K</i> = max(|<i>u</i><sub>0</sub>|, …, |<i>u</i><sub><i>N</i>−1</sub>|, 1 + |<i>L</i>|). Alors |<i>u</i><sub><i>n</i></sub>| ≤ <i>K</i> pour tout <i>n</i>.</p></div>
<div class="idea"><p>Après le rang <i>N</i>, la suite est coincée dans la bande ; avant, elle n’a qu’un nombre fini de termes, qui ne peuvent pas être infiniment grands. C’est le découpage « un nombre fini de termes au début, puis la bande » qui fait tout.</p></div>
<div class="warn"><p>La <b>réciproque est fausse</b> : (−1)<sup><i>n</i></sup> est bornée et diverge. Le théorème sert surtout par <b>contraposée</b> : une suite non bornée, comme <i>n</i>², √<i>n</i> ou (−1)<sup><i>n</i></sup> <i>n</i>, ne peut pas converger.</p></div>
<div class="ex"><p>Pour <i>u</i><sub><i>n</i></sub> = (3<i>n</i> + 1)/(<i>n</i> + 2) → 3, avec ε = 1 on a <i>N</i> = 4 (5/(<i>n</i> + 2) &lt; 1 ⇔ <i>n</i> &gt; 3) ; les termes avant valent 1/2, 4/3, 7/4, 2, tous ≤ 4 = 1 + 3. Donc |<i>u</i><sub><i>n</i></sub>| ≤ 4 pour tout <i>n</i>.</p></div>`},
  {kind:'Théorie',h:'Le théorème des suites monotones bornées',
   p:`<p>Comment prouver qu’une suite converge quand on ne connaît pas sa limite ? Dans ℝ, une suite qui monte sans dépasser un plafond doit s’arrêter quelque part : c’est l’axiome de la borne supérieure qui le dit.</p>
<div class="thm"><p>Toute suite croissante et majorée converge, et sa limite est la borne supérieure de l’ensemble de ses valeurs : lim <i>u</i><sub><i>n</i></sub> = sup {<i>u</i><sub><i>n</i></sub> : <i>n</i> ∈ ℕ}. De même, toute suite décroissante et minorée converge vers la borne inférieure de ses valeurs.</p></div>
<div class="why"><p>L’ensemble <i>A</i> = {<i>u</i><sub><i>n</i></sub>} est non vide et majoré : par l’axiome, <i>s</i> = sup <i>A</i> existe. Soit ε &gt; 0. Par caractérisation de la borne supérieure, il existe un terme <i>u</i><sub><i>N</i></sub> &gt; <i>s</i> − ε. La suite étant croissante, pour tout <i>n</i> ≥ <i>N</i> : <i>s</i> − ε &lt; <i>u</i><sub><i>N</i></sub> ≤ <i>u</i><sub><i>n</i></sub> ≤ <i>s</i> &lt; <i>s</i> + ε, donc |<i>u</i><sub><i>n</i></sub> − <i>s</i>| &lt; ε. C’est la définition : <i>u</i><sub><i>n</i></sub> → <i>s</i>.</p></div>
<div class="idea"><p>Le théorème est un théorème d’<b>existence</b> : il garantit une limite sans la calculer. Il est faux dans ℚ : la suite des approximations décimales 1 ; 1,4 ; 1,41 ; 1,414 ; … est croissante, majorée par 2, formée de rationnels, et sa limite √2 n’est pas dans ℚ. C’est exactement pour cela qu’on a eu besoin de ℝ.</p></div>
<div class="ex"><p><i>u</i><sub><i>n</i></sub> = (2<i>n</i> − 1)/(<i>n</i> + 2) est croissante (méthode plus haut) et majorée par 2 : elle converge, et sa limite est sup {<i>u</i><sub><i>n</i></sub>} = 2.</p></div>
<div class="warn"><p>La limite est la <b>borne supérieure</b>, pas n’importe quel majorant : la suite est aussi majorée par 100, et sa limite n’est pas 100. Et une suite croissante non majorée ne converge pas (elle n’est pas bornée) : elle tend vers +∞, voir plus bas.</p></div>`},
  {h:'Le théorème s’applique-t-il ?',p:'À laquelle de ces suites le théorème des suites monotones bornées permet-il de conclure directement qu’elle converge&nbsp;?',
   opts:['<i>u</i><sub><i>n</i></sub> = (−1)<sup><i>n</i></sup>/<i>n</i>','<i>u</i><sub><i>n</i></sub> = <i>n</i>/(<i>n</i> + 1)','<i>u</i><sub><i>n</i></sub> = √<i>n</i>','<i>u</i><sub><i>n</i></sub> = (−1)<sup><i>n</i></sup>'],ans:1,
   why:'n/(n + 1) est croissante (différence 1/((n + 1)(n + 2)) &gt; 0) et majorée par 1 : elle converge vers sup = 1. (−1)ⁿ/n converge mais n’est pas monotone (le théorème ne s’applique pas, même si la conclusion est vraie) ; √n est croissante non majorée ; (−1)ⁿ est bornée non monotone et diverge.'},
  {kind:'Théorie',h:'Suites qui tendent vers +∞ ou −∞',
   p:`<p>Parmi les suites divergentes, certaines ont un comportement net : elles finissent par dépasser n’importe quel seuil. On leur donne une « limite infinie », avec le vocabulaire des voisinages de l’infini.</p>
<div class="def"><p>(<i>u</i><sub><i>n</i></sub>) <b>tend vers +∞</b>, noté <i>u</i><sub><i>n</i></sub> → +∞, si : <b>∀<i>A</i> ∈ ℝ, ∃<i>N</i> ∈ ℕ, ∀<i>n</i> ≥ <i>N</i>, <i>u</i><sub><i>n</i></sub> &gt; <i>A</i></b>. Elle <b>tend vers −∞</b> si ∀<i>B</i> ∈ ℝ, ∃<i>N</i>, ∀<i>n</i> ≥ <i>N</i>, <i>u</i><sub><i>n</i></sub> &lt; <i>B</i>. Dans les deux cas la suite est <b>divergente</b> : elle ne converge vers aucun réel.</p></div>
<div class="idea"><p>C’est la même phrase que la convergence, où « être dans la bande ]<i>L</i> − ε ; <i>L</i> + ε[ » est remplacé par « être dans le voisinage ]<i>A</i> ; +∞[ ». L’adversaire choisit un seuil <i>A</i> aussi grand qu’il veut ; tu dois trouver un rang à partir duquel la suite reste au-dessus.</p></div>
<div class="prop"><p>Une suite croissante non majorée tend vers +∞. Preuve : soit <i>A</i> réel ; <i>A</i> n’est pas un majorant, donc un terme <i>u</i><sub><i>N</i></sub> &gt; <i>A</i> existe, et par croissance <i>u</i><sub><i>n</i></sub> ≥ <i>u</i><sub><i>N</i></sub> &gt; <i>A</i> pour <i>n</i> ≥ <i>N</i>. Ainsi une suite croissante a toujours une limite, finie ou +∞.</p></div>
<div class="ex"><p><i>u</i><sub><i>n</i></sub> = <i>n</i>² → +∞ : contre <i>A</i>, prends <i>N</i> entier &gt; √|<i>A</i>| ; alors <i>n</i> ≥ <i>N</i> ⇒ <i>n</i>² ≥ <i>N</i>² &gt; <i>A</i>. <i>u</i><sub><i>n</i></sub> = 5 − 3<i>n</i> → −∞.</p></div>
<div class="warn"><p>Diverger ne signifie pas tendre vers l’infini : (−1)<sup><i>n</i></sup> diverge en restant bornée, et (−1)<sup><i>n</i></sup> <i>n</i> n’est pas bornée sans tendre ni vers +∞ ni vers −∞ (elle change de signe sans cesse). « Divergente » couvre tout ce qui n’est pas « convergente vers un réel ».</p></div>`},
  {h:'Dépasser un seuil',p:'Pour <i>u</i><sub><i>n</i></sub> = 3<i>n</i> − 7 et le seuil <i>A</i> = 1000, quel est le plus petit <i>N</i> tel que <i>u</i><sub><i>n</i></sub> &gt; 1000 pour tout <i>n</i> ≥ <i>N</i>&nbsp;?',lab:'N =',ans:336,
   why:'3n − 7 &gt; 1000 ⇔ 3n &gt; 1007 ⇔ n &gt; 335,67. Le premier entier est N = 336 (u₃₃₆ = 1001), et la suite est croissante, donc tous les rangs suivants conviennent.'},
  {kind:'Récapitulatif',h:'Ce qu’il faut retenir',
   p:`<p>La définition de la limite est le cœur de l’analyse : chaque mot compte, et les trois théorèmes de ce chapitre en découlent directement.</p>
<div class="keep"><ul><li><b>Suite</b> : application ℕ → ℝ, notée (<i>u</i><sub><i>n</i></sub>) ; définition explicite ou par récurrence.</li><li><b>Monotone</b> : signe de <i>u</i><sub><i>n</i>+1</sub> − <i>u</i><sub><i>n</i></sub> (ou quotient comparé à 1 si termes &gt; 0). <b>Bornée</b> : |<i>u</i><sub><i>n</i></sub>| ≤ <i>K</i>.</li><li><b><i>u</i><sub><i>n</i></sub> → <i>L</i></b> : ∀ε &gt; 0, ∃<i>N</i>, ∀<i>n</i> ≥ <i>N</i>, |<i>u</i><sub><i>n</i></sub> − <i>L</i>| &lt; ε. <i>N</i> dépend de ε. Négation : ∃ε, ∀<i>N</i>, ∃<i>n</i> ≥ <i>N</i>, |<i>u</i><sub><i>n</i></sub> − <i>L</i>| ≥ ε.</li><li>Méthode : simplifier |<i>u</i><sub><i>n</i></sub> − <i>L</i>|, résoudre &lt; ε en <i>n</i>, choisir <i>N</i> (Archimède).</li><li><b>Unicité</b> de la limite (ε = |<i>L</i> − <i>L</i>′|/2, inégalité triangulaire).</li><li><b>Convergente ⇒ bornée</b> (ε = 1 puis max d’un nombre fini de termes). Réciproque fausse : (−1)<sup><i>n</i></sup>.</li><li><b>Monotone bornée ⇒ convergente</b>, vers le sup (ou l’inf) des valeurs. Faux dans ℚ ; repose sur l’axiome de la borne supérieure.</li><li><b><i>u</i><sub><i>n</i></sub> → +∞</b> : ∀<i>A</i>, ∃<i>N</i>, ∀<i>n</i> ≥ <i>N</i>, <i>u</i><sub><i>n</i></sub> &gt; <i>A</i>. Croissante non majorée ⇒ +∞. Divergente ≠ tend vers ∞.</li></ul></div>`},
  {kind:'Problème',h:'Étude complète d’une suite explicite',
   p:'On considère <i>u</i><sub><i>n</i></sub> = (2<i>n</i> − 1)/(<i>n</i> + 3) pour <i>n</i> ∈ ℕ. On veut en faire l’étude complète avec les outils du chapitre : premiers termes, sens de variation, convergence prouvée avec la définition, rang explicite pour une précision donnée, et caractère borné. On devine la limite <i>L</i> = 2 en regardant les termes de rang élevé.',
   fig:(()=>suite(n=>(2*n-1)/(n+3),{n0:0,N:30,y:[-0.6,2.4],h:190,lx:5,ly:0.5,L:2}).svg())(),
   parts:[
    {q:'a) Calcule <i>u</i><sub>0</sub>. Donne une fraction ou arrondis au millième.',lab:'u₀ =',ans:-1/3,tol:0.001,hint:'Remplace n par 0.',why:'u₀ = (0 − 1)/(0 + 3) = −1/3 ≈ −0,333.'},
    {q:'b) Quel est le sens de variation de (<i>u</i><sub><i>n</i></sub>)&nbsp;?',opts:['Croissante : <i>u</i><sub><i>n</i>+1</sub> − <i>u</i><sub><i>n</i></sub> = 7/((<i>n</i> + 3)(<i>n</i> + 4)) &gt; 0','Décroissante : le dénominateur augmente','Non monotone : <i>u</i><sub>0</sub> est négatif puis les termes sont positifs','Croissante : <i>u</i><sub><i>n</i>+1</sub> − <i>u</i><sub><i>n</i></sub> = 2'],ans:0,hint:'Calcule uₙ₊₁ − uₙ au même dénominateur, comme dans la méthode.',why:'uₙ₊₁ − uₙ = (2n + 1)/(n + 4) − (2n − 1)/(n + 3) = [(2n + 1)(n + 3) − (2n − 1)(n + 4)]/((n + 3)(n + 4)) = (2n² + 7n + 3 − 2n² − 7n + 4)/(…) = 7/((n + 3)(n + 4)) &gt; 0. Le changement de signe des termes n’empêche pas la croissance.'},
    {q:'c) On a |<i>u</i><sub><i>n</i></sub> − 2| = 7/(<i>n</i> + 3). Pour ε = 0,01, quel est le plus petit rang <i>N</i> tel que |<i>u</i><sub><i>n</i></sub> − 2| &lt; 0,01 pour tout <i>n</i> ≥ <i>N</i>&nbsp;?',lab:'N =',ans:698,hint:'Résous 7/(n + 3) &lt; 0,01 ; attention à l’inégalité stricte.',why:'7/(n + 3) &lt; 0,01 ⇔ n + 3 &gt; 700 ⇔ n &gt; 697. Donc N = 698 (pour n = 697, l’écart vaut exactement 0,01). Comme 7/(n + 3) décroît, tous les rangs suivants conviennent : c’est la définition de uₙ → 2.'},
    {q:'d) La suite est-elle bornée&nbsp;?',opts:['Non : elle est croissante, donc non majorée','Oui : −1/3 ≤ <i>u</i><sub><i>n</i></sub> &lt; 2 pour tout <i>n</i>, et de toute façon une suite convergente est bornée','Non : les premiers termes sont négatifs','On ne peut pas savoir sans calculer tous les termes'],ans:1,hint:'Deux arguments possibles : un encadrement direct, ou un théorème du chapitre.',why:'Croissante donc minorée par u₀ = −1/3 ; et 2 − uₙ = 7/(n + 3) &gt; 0 donc majorée par 2. Le théorème « convergente ⇒ bornée » le garantissait d’avance. Croissante ne veut pas dire non majorée.'},
   ],
   sol:'<i>u</i><sub>0</sub> = −1/3, <i>u</i><sub>1</sub> = 1/4, <i>u</i><sub>2</sub> = 3/5, … La différence <i>u</i><sub><i>n</i>+1</sub> − <i>u</i><sub><i>n</i></sub> = 7/((<i>n</i> + 3)(<i>n</i> + 4)) est strictement positive : la suite est <b>strictement croissante</b>. Écart à 2 : <i>u</i><sub><i>n</i></sub> − 2 = (2<i>n</i> − 1 − 2<i>n</i> − 6)/(<i>n</i> + 3) = −7/(<i>n</i> + 3), donc |<i>u</i><sub><i>n</i></sub> − 2| = 7/(<i>n</i> + 3). Soit ε &gt; 0 ; 7/(<i>n</i> + 3) &lt; ε dès que <i>n</i> &gt; 7/ε − 3, et un tel entier <i>N</i> existe (Archimède) ; pour <i>n</i> ≥ <i>N</i> l’inégalité reste vraie car l’écart décroît : <b><i>u</i><sub><i>n</i></sub> → 2</b>. Pour ε = 0,01, <i>N</i> = 698. Enfin −1/3 ≤ <i>u</i><sub><i>n</i></sub> &lt; 2 : la suite est bornée, comme toute suite convergente. On retrouve aussi la convergence par le théorème des suites monotones : croissante et majorée par 2, elle converge vers sup {<i>u</i><sub><i>n</i></sub>} = 2.'},
  {kind:'Problème',h:'Une suite récurrente qui converge sans qu’on calcule sa limite',
   p:'On définit (<i>u</i><sub><i>n</i></sub>) par <i>u</i><sub>0</sub> = 0 et <i>u</i><sub><i>n</i>+1</sub> = √(<i>u</i><sub><i>n</i></sub> + 2). Aucune formule explicite n’est disponible. On veut prouver que la suite converge en montrant qu’elle est croissante et majorée par 2, grâce à deux raisonnements par récurrence. On utilise que la racine carrée conserve l’ordre : 0 ≤ <i>a</i> &lt; <i>b</i> ⇒ √<i>a</i> &lt; √<i>b</i> (sinon √<i>a</i> ≥ √<i>b</i> donnerait <i>a</i> ≥ <i>b</i> en élevant au carré).',
   parts:[
    {q:'a) Calcule <i>u</i><sub>3</sub>, arrondi au millième.',lab:'u₃ ≈',ans:1.962,tol:0.002,hint:'u₁ = √2, u₂ = √(2 + √2), puis encore une étape.',why:'u₁ = √2 ≈ 1,4142 ; u₂ = √(2 + 1,4142) ≈ 1,8478 ; u₃ = √(2 + 1,8478) = √3,8478 ≈ 1,9616.'},
    {q:'b) On montre par récurrence que <i>u</i><sub><i>n</i></sub> &lt; 2 pour tout <i>n</i>. Quel est le pas de récurrence correct&nbsp;?',opts:['Si <i>u</i><sub><i>n</i></sub> &lt; 2, alors <i>u</i><sub><i>n</i></sub> + 2 &lt; 4, donc <i>u</i><sub><i>n</i>+1</sub> = √(<i>u</i><sub><i>n</i></sub> + 2) &lt; √4 = 2','Si <i>u</i><sub><i>n</i></sub> &lt; 2, alors <i>u</i><sub><i>n</i>+1</sub> = <i>u</i><sub><i>n</i></sub> + 2 − 2 &lt; 2','<i>u</i><sub>3</sub> ≈ 1,96 &lt; 2, donc tous les termes sont &lt; 2','Si <i>u</i><sub><i>n</i></sub> &lt; 2, alors √<i>u</i><sub><i>n</i></sub> &lt; √2 &lt; 2'],ans:0,hint:'Pars de l’hypothèse uₙ &lt; 2, ajoute 2, puis applique la racine (qui conserve l’ordre).',why:'u₀ = 0 &lt; 2 (initialisation). Si uₙ &lt; 2, alors uₙ + 2 &lt; 4 et, la racine conservant l’ordre, uₙ₊₁ &lt; 2 (hérédité). Un exemple numérique ne prouve rien pour tout n.'},
    {q:'c) Pour montrer que la suite est croissante, on calcule <i>u</i><sub><i>n</i>+1</sub>² − <i>u</i><sub><i>n</i></sub>² = <i>u</i><sub><i>n</i></sub> + 2 − <i>u</i><sub><i>n</i></sub>². Comment se factorise cette expression&nbsp;?',opts:['(<i>u</i><sub><i>n</i></sub> − 2)(<i>u</i><sub><i>n</i></sub> + 1)','(2 − <i>u</i><sub><i>n</i></sub>)(1 + <i>u</i><sub><i>n</i></sub>)','(<i>u</i><sub><i>n</i></sub> − 1)(<i>u</i><sub><i>n</i></sub> + 2)','(2 − <i>u</i><sub><i>n</i></sub>)²'],ans:1,hint:'Développe les options : il faut retrouver −uₙ² + uₙ + 2.',why:'(2 − u)(1 + u) = 2 + 2u − u − u² = 2 + u − u². Comme 0 ≤ uₙ &lt; 2, les deux facteurs sont strictement positifs : uₙ₊₁² &gt; uₙ², et comme les termes sont positifs, uₙ₊₁ &gt; uₙ.'},
    {q:'d) Que peut-on conclure&nbsp;?',opts:['La suite converge vers 2, car 2 est un majorant','La suite est croissante et majorée, donc elle converge vers un réel ℓ ≤ 2 (théorème des suites monotones bornées)','La suite tend vers +∞ car elle est croissante','On ne peut rien conclure sans formule explicite'],ans:1,hint:'Quel théorème garantit une limite sans la calculer ?',why:'Croissante et majorée par 2 : le théorème des suites monotones bornées assure la convergence vers ℓ = sup {uₙ} ≤ 2. Que ℓ vaille exactement 2 est vrai, mais demande un argument supplémentaire (passage à la limite dans la relation de récurrence), vu plus loin.'},
   ],
   sol:'<b>Majoration.</b> <i>u</i><sub>0</sub> = 0 &lt; 2 ; si <i>u</i><sub><i>n</i></sub> &lt; 2, alors <i>u</i><sub><i>n</i></sub> + 2 &lt; 4 et <i>u</i><sub><i>n</i>+1</sub> = √(<i>u</i><sub><i>n</i></sub> + 2) &lt; 2. Par récurrence, 0 ≤ <i>u</i><sub><i>n</i></sub> &lt; 2 pour tout <i>n</i>. <b>Croissance.</b> <i>u</i><sub><i>n</i>+1</sub>² − <i>u</i><sub><i>n</i></sub>² = 2 + <i>u</i><sub><i>n</i></sub> − <i>u</i><sub><i>n</i></sub>² = (2 − <i>u</i><sub><i>n</i></sub>)(1 + <i>u</i><sub><i>n</i></sub>) &gt; 0, et deux nombres positifs sont rangés comme leurs carrés : <i>u</i><sub><i>n</i>+1</sub> &gt; <i>u</i><sub><i>n</i></sub>. <b>Conclusion.</b> La suite est croissante et majorée par 2 : par le théorème des suites monotones bornées, elle converge vers ℓ = sup {<i>u</i><sub><i>n</i></sub>}, avec ℓ ≤ 2. Numériquement, <i>u</i><sub>3</sub> ≈ 1,962 et les termes s’approchent de 2 ; la preuve que ℓ = 2 exactement viendra avec les opérations sur les limites.'},
]},
);
})();
